insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('besan-chilla', 'Besan Chilla', '{"en": "Besan Chilla", "hi": "बेसन चीला", "hi-Latn": "Besan Chilla"}'::jsonb, 'Thin savoury pancakes of gram flour with onion, tomato and coriander, cooked on the tawa. Ready in twenty minutes.', '{"hi": "बेसन के पतले नमकीन चीले, प्याज़, टमाटर और धनिए के साथ, तवे पर बने। बीस मिनट में तैयार।", "hi-Latn": "Besan ke patle namkeen cheele, pyaaz, tamatar aur dhaniye ke saath, tawe par bane. Bees minute mein taiyaar."}'::jsonb, 'generic_north', 'breakfast', 'vegan', 4, 15, 20, 2, 2, array['tawa']::text[], array['quick', 'high_protein', 'tiffin']::text[], '{"acid": 0.2, "crunch": 0.3, "heat": 0.3, "rich": 0.3, "starch": 0.4, "sweet": 0}'::jsonb, array['dal']::text[], 'curated', 'draft', false)
