insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'besan-chilla'), 1, 'Whisk the besan with turmeric, chilli powder, ajwain, salt and about 250 ml water into a smooth batter. Rest it for 10 minutes.', '{"en": "Whisk the besan with turmeric, chilli powder, ajwain, salt and about 250 ml water into a smooth batter. Rest it for 10 minutes.", "hi": {"branch": "हरी मिर्च डालने से पहले बच्चे के चीले पहले बना लें", "look": "घोल चिकना और बहने वाला हो, पतले डोसे के घोल जैसा, कोई गाँठ न हो।", "text": "बेसन में हल्दी, मिर्च पाउडर, अजवाइन, नमक और लगभग 250 ml पानी डालकर फेंटें, चिकना घोल बनाएँ। 10 मिनट रखा रहने दें।", "touch": "घोल व्हिस्क से एक लगातार धार में गिरे।"}, "hi-Latn": {"branch": "Hari mirch daalne se pehle bachche ke cheele pehle bana lein", "look": "Ghol chikna aur behne wala ho, patle dosa ghol jaisa, koi gaanth na ho.", "text": "Besan mein haldi, mirch powder, ajwain, namak aur lagbhag 250 ml paani daalkar phentein, chikna ghol banaayein. 10 minute rakha rehne dein.", "touch": "Ghol whisk se ek lagaataar dhaar mein gire."}}'::jsonb, (select id from public.techniques where slug = 'batter'), 600, true, null, 'Smooth and pourable, like thin dosa batter. No lumps.', '{"en": "Smooth and pourable, like thin dosa batter. No lumps.", "look": "Smooth and pourable, like thin dosa batter, with no lumps.", "touch": "It runs off the whisk in a steady ribbon."}'::jsonb, '{"action": "Make the child''s chillas first, before the green chilli goes into the batter", "age_group": "child"}'::jsonb, null),
  ((select id from public.recipes where household_id is null and slug = 'besan-chilla'), 2, 'Stir in the finely chopped onion, tomato, green chilli and coriander.', '{"en": "Stir in the finely chopped onion, tomato, green chilli and coriander.", "hi": {"look": "सब्ज़ियाँ पूरे घोल में बराबर फैली हों।", "text": "बारीक कटा प्याज़, टमाटर, हरी मिर्च और धनिया मिला दें।"}, "hi-Latn": {"look": "Sabziyaan poore ghol mein barabar faili hon.", "text": "Bareek kata pyaaz, tamatar, hari mirch aur dhaniya mila dein."}}'::jsonb, null, 120, false, null, 'The vegetables are spread evenly through the batter.', '{"en": "The vegetables are spread evenly through the batter.", "look": "The vegetables are spread evenly through the batter."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'besan-chilla'), 3, 'Heat the tawa on medium and grease it lightly. Pour a ladle of batter in the centre and spread it into a thin circle. Drizzle a little oil around the edge.', '{"en": "Heat the tawa on medium and grease it lightly. Pour a ladle of batter in the centre and spread it into a thin circle. Drizzle a little oil around the edge.", "hi": {"avoid": "अगर तवे से धुआँ निकले तो कुछ सेकंड आँच से हटा लें, वरना चीला चिपक कर जल जाएगा।", "look": "छोटे-छोटे बुलबुले आएँ और किनारे अपने आप उठने लगें।", "sound": "घोल तवे पर पड़ते ही हल्की छन-छन आवाज़ आए।", "text": "तवा मध्यम आँच पर गरम करें और हल्का तेल लगाएँ। बीच में एक कलछी घोल डालें और पतला गोल फैलाएँ। किनारों पर थोड़ा तेल डालें।"}, "hi-Latn": {"avoid": "Agar tawe se dhuaan nikle to kuch second aanch se hata lein, warna cheela chipak kar jal jaayega.", "look": "Chhote-chhote bulbule aayein aur kinaare apne aap uthne lagein.", "sound": "Ghol tawe par padte hi halki chhan-chhan awaaz aaye.", "text": "Tawa madhyam aanch par garam karein aur halka tel lagaayein. Beech mein ek kalchhi ghol daalein aur patla gol phailaayein. Kinaaron par thoda tel daalein."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 120, false, null, 'Small bubbles appear and the edges start to lift on their own.', '{"avoid": "If the tawa smokes, take it off the flame for a few seconds first, or the chilla sticks and burns.", "en": "Small bubbles appear and the edges start to lift on their own.", "heat": "medium", "look": "Small bubbles appear and the edges lift on their own.", "sound": "A gentle sizzle when the batter touches the tawa."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'besan-chilla'), 4, 'Flip and cook the other side, pressing gently. Repeat with the rest of the batter.', '{"en": "Flip and cook the other side, pressing gently. Repeat with the rest of the batter.", "hi": {"look": "दोनों तरफ़ सुनहरे-भूरे निशान हों और बीच में गीला घोल न हो।", "smell": "भुने बेसन की ख़ुशबू आए, कच्चे आटे की नहीं।", "text": "पलटें और हल्का दबाते हुए दूसरी तरफ़ सेकें। बाकी घोल से ऐसे ही बनाएँ।", "touch": "पलटे से दबाने पर बीच का हिस्सा वापस उभर आए।"}, "hi-Latn": {"look": "Dono taraf sunehre-bhoore nishaan hon aur beech mein geela ghol na ho.", "smell": "Bhune besan ki khushboo aaye, kachche aate ki nahi.", "text": "Paltein aur halka dabaate hue doosri taraf sekein. Baaki ghol se aise hi banaayein.", "touch": "Palte se dabaane par beech ka hissa waapas ubhar aaye."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 900, false, null, 'Golden-brown spots on both sides and no raw batter in the middle.', '{"en": "Golden-brown spots on both sides and no raw batter in the middle.", "heat": "medium", "look": "Golden-brown spots on both sides and no wet batter in the middle.", "smell": "Roasted besan, not raw flour.", "touch": "The middle springs back when pressed with the spatula."}'::jsonb, null, null)
