-- Recipe: bhatura (draft, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('bhatura', 'Bhatura', '{"en": "Bhatura", "hi": "भटूरा", "hi-Latn": "Bhatura"}'::jsonb, 'Big puffy bhaturas for chole. A soft maida dough with curd and a pinch of soda that rests for two hours, so plan ahead.', '{"hi": "छोले के साथ बड़े फूले भटूरे। दही और चुटकी भर सोडा वाला नरम मैदे का आटा जो दो घंटे रखा जाता है, इसलिए पहले से तैयारी करें।", "hi-Latn": "Chhole ke saath bade phoole bhature. Dahi aur chutki bhar soda waala naram maide ka aata jo do ghante rakha jaata hai, isliye pehle se taiyaari karein."}'::jsonb, 'generic_north', 'component', 'veg', 2, 135, 15, 3, 1, array['kadai']::text[], array['basics', 'festive']::text[], '{"acid": 0.2, "crunch": 0.3, "heat": 0, "rich": 0.6, "starch": 1, "sweet": 0.1}'::jsonb, array['grain']::text[], 'curated', 'draft', false)
