insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'bhatura'), 1, 'Mix maida, suji, soda, sugar and salt. Add the curd and one spoon of oil, then lukewarm water a little at a time, and knead a soft dough.', '{"en": "Mix maida, suji, soda, sugar and salt. Add the curd and one spoon of oil, then lukewarm water a little at a time, and knead a soft dough.", "hi": {"text": "मैदा, सूजी, सोडा, चीनी और नमक मिलाएँ। दही और एक चम्मच तेल डालें, फिर गुनगुना पानी थोड़ा-थोड़ा डालकर नरम आटा गूँधें।", "touch": "नरम और चिकना, रोटी के आटे से थोड़ा नरम, चिपचिपा नहीं।"}, "hi-Latn": {"text": "Maida, suji, soda, cheeni aur namak milaayein. Dahi aur ek chammach tel daalein, phir gunguna paani thoda-thoda daal kar naram aata goondhein.", "touch": "Naram aur chikna, roti ke aate se thoda naram, chipchipa nahi."}}'::jsonb, (select id from public.techniques where slug = 'knead'), 480, false, null, 'Soft and smooth, a little softer than roti dough, and not sticky.', '{"en": "Soft and smooth, a little softer than roti dough, and not sticky.", "touch": "Soft and smooth, a little softer than roti dough, and not sticky."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'bhatura'), 2, 'Coat with a little oil, cover and leave in a warm place to rest.', '{"en": "Coat with a little oil, cover and leave in a warm place to rest.", "hi": {"look": "आटा थोड़ा फूला हुआ दिखे।", "smell": "दही की हल्की खट्टी ख़ुशबू।", "text": "थोड़ा तेल लगाएँ, ढकें और गरम जगह पर रखें।"}, "hi-Latn": {"look": "Aata thoda phoola hua dikhe.", "smell": "Dahi ki halki khatti khushboo.", "text": "Thoda tel lagaayein, dhakein aur garam jagah par rakhein."}}'::jsonb, null, 7200, true, null, 'The dough looks slightly puffed. A light sour smell from the curd.', '{"en": "The dough looks slightly puffed. A light sour smell from the curd.", "look": "The dough looks slightly puffed.", "smell": "A light sour smell from the curd."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'bhatura'), 3, 'Heat the oil well. Roll a ball into an oval a little thicker than a roti, using oil instead of dry flour.', '{"en": "Heat the oil well. Roll a ball into an oval a little thicker than a roti, using oil instead of dry flour.", "hi": {"look": "आटे का टुकड़ा डालते ही ऊपर आ जाए: तेल तैयार है।", "safety": "बच्चों को कड़ाही से दूर रखें और गरम तेल को कभी अकेला न छोड़ें।", "text": "तेल अच्छी तरह गरम करें। लोई को रोटी से थोड़ा मोटा लंबा गोल बेलें, सूखे आटे की जगह तेल लगाकर।"}, "hi-Latn": {"look": "Aate ka tukda daalte hi upar aa jaaye: tel taiyaar hai.", "safety": "Bachchon ko kadaahi se door rakhein aur garam tel ko kabhi akela na chhodein.", "text": "Tel achchhi tarah garam karein. Loi ko roti se thoda mota lamba gol belein, sookhe aate ki jagah tel lagaakar."}}'::jsonb, (select id from public.techniques where slug = 'deep_fry'), 300, false, null, 'A pinch of dough rises to the top at once: the oil is ready.', '{"en": "A pinch of dough rises to the top at once: the oil is ready.", "heat": "high", "look": "A pinch of dough rises to the top at once: the oil is ready."}'::jsonb, null, 'Keep children away from the kadai and never leave hot oil alone.'),
  ((select id from public.recipes where household_id is null and slug = 'bhatura'), 4, 'Slide one in, keep pressing gently and spooning oil over it until it puffs fully, flip once and fry until light golden.', '{"en": "Slide one in, keep pressing gently and spooning oil over it until it puffs fully, flip once and fry until light golden.", "hi": {"avoid": "अगर न फूले तो आटे को और आराम चाहिए या तेल कम गरम है।", "look": "बड़े गुब्बारे की तरह फूले और हल्का सुनहरा हो, कहीं-कहीं गहरे धब्बे।", "safety": "तेल के पास से धीरे डालें ताकि छींटे न उड़ें।", "text": "एक भटूरा डालें, हल्के से दबाते रहें और ऊपर तेल डालते रहें जब तक पूरा न फूल जाए, एक बार पलटें और हल्का सुनहरा तलें।"}, "hi-Latn": {"avoid": "Agar na phoole to aate ko aur aaraam chaahiye ya tel kam garam hai.", "look": "Bade gubbaare ki tarah phoole aur halka sunehra ho, kahin-kahin gehre dhabbe.", "safety": "Tel ke paas se dheere daalein taaki chheente na udein.", "text": "Ek bhatura daalein, halke se dabaate rahein aur upar tel daalte rahein jab tak poora na phool jaaye, ek baar paltein aur halka sunehra talein."}}'::jsonb, (select id from public.techniques where slug = 'deep_fry'), 60, false, null, 'It puffs into a big balloon and turns pale golden with darker spots. If it doesn''t puff, the dough needs more rest or the oil isn''t hot enough.', '{"avoid": "If it doesn''t puff, the dough needs more rest or the oil isn''t hot enough.", "en": "It puffs into a big balloon and turns pale golden with darker spots. If it doesn''t puff, the dough needs more rest or the oil isn''t hot enough.", "heat": "high", "look": "It puffs into a big balloon and turns pale golden with darker spots."}'::jsonb, null, 'Slide it in close to the oil so it doesn''t splash.')
