-- Recipe: boiled-chana (draft, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('boiled-chana', 'Boiled Chana', '{"en": "Boiled Chana", "hi": "उबले छोले", "hi-Latn": "Ubale Chole"}'::jsonb, 'Soak and pressure-cook a big batch on Sunday. Kept in the fridge (three days) or frozen in portions, it turns a weekday chole, rajma or chaat into a half-hour job.', '{"hi": "रविवार को एक बड़ा बैच भिगोकर कुकर में उबाल लें। फ़्रिज में (तीन दिन) या हिस्सों में जमाकर रखें, तो हफ़्ते में छोले, राजमा या चाट आधे घंटे का काम है।", "hi-Latn": "Ravivaar ko ek bada batch bhigo kar cooker mein ubaal lein. Fridge mein (teen din) ya hisson mein jama kar rakhein, to hafte mein chole, rajma ya chaat aadhe ghante ka kaam hai."}'::jsonb, 'generic_north', 'component', 'vegan', 8, 480, 35, 1, 1, array['pressure_cooker']::text[], array['basics', 'high_protein']::text[], '{"acid": 0, "crunch": 0, "heat": 0, "rich": 0.3, "starch": 0.6, "sweet": 0}'::jsonb, array['dal', 'protein']::text[], 'curated', 'draft', false)
