  ((select id from public.recipes where household_id is null and slug = 'boiled-chana'), (select id from public.ingredients where canonical_name = 'salt'), 'salt', 6, 'g', '1 chhota chammach', false, null, 'spice', '[]'::jsonb, 1);

insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'boiled-chana'), 1, 'Rinse the chana and soak in plenty of water overnight.', '{"en": "Rinse the chana and soak in plenty of water overnight.", "hi": {"look": "दुगने हो जाएँ और छिलका चिकना और कसा दिखे।", "text": "चने धोकर रात भर ढेर सारे पानी में भिगो दें।"}, "hi-Latn": {"look": "Dugne ho jaayein aur chhilka chikna aur kasa dikhe.", "text": "Chane dho kar raat bhar dher saare paani mein bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 28800, false, null, 'They double in size and the skins look smooth and tight.', '{"en": "They double in size and the skins look smooth and tight.", "look": "They double in size and the skins look smooth and tight."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'boiled-chana'), 2, 'Drain, add fresh water to cover by two fingers and the salt, and pressure-cook for 6 whistles (rajma 8), then let the pressure drop by itself.', '{"en": "Drain, add fresh water to cover by two fingers and the salt, and pressure-cook for 6 whistles (rajma 8), then let the pressure drop by itself.", "hi": {"safety": "राजमा पूरी तरह नरम होना चाहिए; कच्चा राजमा खाना सुरक्षित नहीं। प्रेशर उतरने पर ही कुकर खोलें।", "sound": "सीटियाँ गिनें, फिर प्रेशर उतरने तक रुकें।", "text": "पानी निकालें, दो उँगली ऊपर तक ताज़ा पानी और नमक डालें, और 6 सीटी (राजमा 8) लगाएँ, फिर प्रेशर अपने आप उतरने दें।", "touch": "दो उँगलियों के बीच दबाने पर आसानी से मसल जाए।"}, "hi-Latn": {"safety": "Rajma poori tarah naram hona chahiye; kachcha rajma khaana surakshit nahi. Pressure utarne par hi cooker kholein.", "sound": "Seetiyaan ginein, phir pressure utarne tak rukein.", "text": "Paani nikaalein, do ungli upar tak taaza paani aur namak daalein, aur 6 seeti (rajma 8) lagaayein, phir pressure apne aap utarne dein.", "touch": "Do ungliyon ke beech dabaane par aasaani se masal jaaye."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 2100, false, 6, 'Count the whistles, then wait for the pressure to drop. One pressed between two fingers mashes easily.', '{"en": "Count the whistles, then wait for the pressure to drop. One pressed between two fingers mashes easily.", "heat": "medium", "sound": "Count the whistles, then wait for the pressure to drop.", "touch": "One pressed between two fingers mashes easily."}'::jsonb, null, 'Rajma must be fully soft; undercooked kidney beans are unsafe to eat. Open the cooker only when the pressure has dropped.'),
  ((select id from public.recipes where household_id is null and slug = 'boiled-chana'), 3, 'Cool, then keep with a little of the cooking water in closed boxes in the fridge, or freeze in portions.', '{"en": "Cool, then keep with a little of the cooking water in closed boxes in the fridge, or freeze in portions.", "hi": {"safety": "फ़्रिज में 3 दिन, फ़्रीज़र में एक महीना चलता है।", "text": "ठंडा करें, फिर थोड़े पकने वाले पानी के साथ बंद डिब्बों में फ़्रिज में रखें, या हिस्सों में जमा दें।", "touch": "फ़्रिज में रखने से पहले ठंडा हो।"}, "hi-Latn": {"safety": "Fridge mein 3 din, freezer mein ek mahina chalta hai.", "text": "Thanda karein, phir thode pakne waale paani ke saath band dibbon mein fridge mein rakhein, ya hisson mein jama dein.", "touch": "Fridge mein rakhne se pehle thanda ho."}}'::jsonb, null, 900, false, null, 'Cool before the boxes go in the fridge.', '{"en": "Cool before the boxes go in the fridge.", "touch": "Cool before the boxes go in the fridge."}'::jsonb, null, 'Keeps 3 days in the fridge or a month frozen.')
