  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('chicken-curry', 'Chicken Curry', '{"en": "Chicken Curry", "hi": "चिकन करी", "hi-Latn": "Chicken Curry"}'::jsonb, 'Home-style bone-in chicken in a browned onion and tomato gravy with whole spices. Good with rice or roti.', '{"hi": "घर जैसा हड्डी वाला चिकन, भुने प्याज़-टमाटर की ग्रेवी और साबुत मसालों के साथ। चावल या रोटी के साथ अच्छा।", "hi-Latn": "Ghar jaisa haddi wala chicken, bhune pyaaz-tamatar ki gravy aur saabut masaalon ke saath. Chaawal ya roti ke saath achha."}'::jsonb, 'generic_north', 'main', 'nonveg', 4, 40, 50, 3, 3, array['kadai']::text[], array['comforting', 'high_protein']::text[], '{"acid": 0.4, "crunch": 0, "heat": 0.5, "rich": 0.7, "starch": 0, "sweet": 0.1}'::jsonb, array['protein']::text[], 'curated', 'draft', false)
