insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 1, 'Mix the chicken with the curd, half the ginger garlic paste, half the turmeric, half the chilli powder and a little salt. Cover and keep in the fridge.', '{"en": "Mix the chicken with the curd, half the ginger garlic paste, half the turmeric, half the chilli powder and a little salt. Cover and keep in the fridge.", "hi": {"look": "हर टुकड़े पर मसाला अच्छे से लगा हो।", "safety": "कच्चा चिकन छूने के बाद हाथ, बोर्ड और चाकू साबुन से धोएँ, और कच्चे चिकन को बिना पके खाने से दूर रखें। मैरिनेट फ्रिज में करें, बाहर नहीं।", "text": "चिकन में दही, आधा अदरक-लहसुन पेस्ट, आधी हल्दी, आधा मिर्च पाउडर और थोड़ा नमक मिलाएँ। ढककर फ्रिज में रखें।"}, "hi-Latn": {"look": "Har tukde par masala achhe se laga ho.", "safety": "Kachcha chicken chhoone ke baad haath, board aur chaaku saabun se dhoyein, aur kachche chicken ko bina pake khaane se door rakhein. Marinate fridge mein karein, bahar nahi.", "text": "Chicken mein dahi, aadha adrak-lahsun paste, aadhi haldi, aadha mirch powder aur thoda namak milaayein. Dhak kar fridge mein rakhein."}}'::jsonb, (select id from public.techniques where slug = 'marinate'), 1800, true, null, 'Every piece is coated in the marinade.', '{"en": "Every piece is coated in the marinade.", "look": "Every piece is coated in the marinade."}'::jsonb, null, 'Wash your hands, the board and the knife with soap after handling raw chicken, and keep raw chicken away from food that will not be cooked. Marinate in the fridge, not on the counter.'),
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 2, 'Heat the oil in a heavy kadai. Add the whole spices for 30 seconds, then the sliced onions. Cook, stirring more often as they colour.', '{"en": "Heat the oil in a heavy kadai. Add the whole spices for 30 seconds, then the sliced onions. Cook, stirring more often as they colour.", "hi": {"avoid": "किनारे काले न होने दें, वरना करी कड़वी हो जाएगी।", "look": "प्याज़ हर तरफ़ से गहरे सुनहरे-भूरे हो जाएँ।", "smell": "मीठी, कैरामल जैसी ख़ुशबू।", "sound": "प्याज़ का पानी सूखने पर छन-छन धीमी हो जाए।", "text": "भारी कड़ाही में तेल गरम करें। साबुत मसाले 30 सेकंड डालें, फिर कटे प्याज़। प्याज़ का रंग बदलने लगे तो ज़्यादा चलाते रहें।"}, "hi-Latn": {"avoid": "Kinaare kaale na hone dein, warna curry kadvi ho jaayegi.", "look": "Pyaaz har taraf se gehre sunehre-bhoore ho jaayein.", "smell": "Meethi, caramel jaisi khushboo.", "sound": "Pyaaz ka paani sookhne par chhan-chhan dheemi ho jaaye.", "text": "Bhaari kadaahi mein tel garam karein. Saabut masaale 30 second daalein, phir kate pyaaz. Pyaaz ka rang badalne lage to zyaada chalaate rahein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 840, false, null, 'The onions are deep golden brown all over, not black at the edges.', '{"avoid": "Don''t let the edges go black: the curry turns bitter.", "en": "The onions are deep golden brown all over, not black at the edges.", "heat": "medium", "look": "The onions are deep golden brown all over.", "smell": "Sweet and caramel-like.", "sound": "The sizzle softens as the onions lose their water."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 3, 'Add the rest of the ginger garlic paste for a minute, then the chopped tomatoes, the remaining turmeric and chilli powder, coriander powder and salt. Cook, stirring.', '{"en": "Add the rest of the ginger garlic paste for a minute, then the chopped tomatoes, the remaining turmeric and chilli powder, coriander powder and salt. Cook, stirring.", "hi": {"look": "टमाटर मसाले में घुल जाएँ और किनारों पर तेल चमकने लगे।", "smell": "कच्चे अदरक-लहसुन की महक चली जाए।", "text": "बचा अदरक-लहसुन पेस्ट एक मिनट भूनें, फिर कटे टमाटर, बची हल्दी और मिर्च पाउडर, धनिया पाउडर और नमक डालें। चलाते हुए पकाएँ।", "touch": "मसाला कड़ाही से एक नरम गोले की तरह अलग होने लगे।"}, "hi-Latn": {"look": "Tamatar masaale mein ghul jaayein aur kinaaron par tel chamakne lage.", "smell": "Kachche adrak-lahsun ki mehak chali jaaye.", "text": "Bacha adrak-lahsun paste ek minute bhoonein, phir kate tamatar, bachi haldi aur mirch powder, dhaniya powder aur namak daalein. Chalaate hue pakaayein.", "touch": "Masala kadaahi se ek naram gole ki tarah alag hone lage."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 480, false, null, 'The tomatoes melt into the masala and oil shines at the edges.', '{"en": "The tomatoes melt into the masala and oil shines at the edges.", "heat": "medium", "look": "The tomatoes melt into the masala and oil shines at the edges.", "smell": "The raw ginger-garlic smell is gone.", "touch": "The masala comes away from the pan in one soft mass."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 4, 'Add the chicken with all its marinade. Cook on high heat, stirring, so it sears and the masala coats every piece.', '{"en": "Add the chicken with all its marinade. Cook on high heat, stirring, so it sears and the masala coats every piece.", "hi": {"avoid": "चलाते रहें ताकि मसाला तले में न लगे।", "look": "हर टुकड़ा बाहर से सफ़ेद हो जाए और मसाले से ढका हो।", "sound": "चिकन डालते ही तेज़ छन-छन आवाज़।", "text": "चिकन को उसके पूरे मसाले के साथ डालें। तेज़ आँच पर चलाते हुए पकाएँ ताकि चिकन सिक जाए और हर टुकड़े पर मसाला लग जाए।"}, "hi-Latn": {"avoid": "Chalaate rahein taaki masala tale mein na lage.", "look": "Har tukda bahar se safed ho jaaye aur masaale se dhaka ho.", "sound": "Chicken daalte hi tez chhan-chhan awaaz.", "text": "Chicken ko uske poore masaale ke saath daalein. Tez aanch par chalaate hue pakaayein taaki chicken sik jaaye aur har tukde par masala lag jaaye."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 360, false, null, 'The chicken turns opaque on the outside.', '{"avoid": "Keep stirring so the masala doesn''t catch on the bottom.", "en": "The chicken turns opaque on the outside.", "heat": "high", "look": "Every piece turns opaque on the outside and is coated in masala.", "sound": "A loud sizzle when the chicken goes in."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 5, 'Add 300 ml hot water, cover and simmer on low heat, stirring now and then.', '{"en": "Add 300 ml hot water, cover and simmer on low heat, stirring now and then.", "hi": {"look": "ग्रेवी धीरे-धीरे उबले और ऊपर तेल आ जाए।", "safety": "चिकन पूरा पका होना चाहिए। सबसे मोटा टुकड़ा हड्डी तक काटें; मांस सफ़ेद हो, गुलाबी न हो और रस साफ़ हो। शक हो तो 5 मिनट और पकाकर फिर देखें।", "text": "300 ml गरम पानी डालें, ढककर धीमी आँच पर पकाएँ, बीच-बीच में चलाते रहें।", "touch": "मांस हड्डी से आसानी से अलग हो जाए; सबसे बड़ा टुकड़ा काटकर देखें: अंदर गुलाबी न हो।"}, "hi-Latn": {"look": "Gravy dheere-dheere ubale aur upar tel aa jaaye.", "safety": "Chicken poora paka hona chahiye. Sabse mota tukda haddi tak kaatein; maas safed ho, gulaabi na ho aur ras saaf ho. Shak ho to 5 minute aur pakaakar phir dekhein.", "text": "300 ml garam paani daalein, dhak kar dheemi aanch par pakaayein, beech-beech mein chalaate rahein.", "touch": "Maas haddi se aasaani se alag ho jaaye; sabse bada tukda kaatkar dekhein: andar gulaabi na ho."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 1500, true, null, 'The meat pulls away from the bone easily.', '{"en": "The meat pulls away from the bone easily.", "heat": "low", "look": "The gravy bubbles gently, with oil on top.", "touch": "The meat pulls away from the bone easily; cut the largest piece: no pink inside."}'::jsonb, null, 'Chicken must be cooked through. Cut the thickest piece open to the bone; the meat should be white with no pink and the juices clear. If unsure, cook 5 more minutes and check again.'),
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 6, 'Add the garam masala and coriander leaves, cover and rest for 5 minutes before serving.', '{"en": "Add the garam masala and coriander leaves, cover and rest for 5 minutes before serving.", "hi": {"smell": "ताज़े गरम मसाले और धनिए की ख़ुशबू।", "text": "गरम मसाला और हरा धनिया डालें, ढककर 5 मिनट रखें, फिर परोसें।"}, "hi-Latn": {"smell": "Taaze garam masaale aur dhaniye ki khushboo.", "text": "Garam masala aur hara dhaniya daalein, dhak kar 5 minute rakhein, phir parosein."}}'::jsonb, null, 300, false, null, 'Fresh garam masala and coriander.', '{"en": "Fresh garam masala and coriander.", "smell": "Fresh garam masala and coriander."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'chicken-curry') and step_no > 6;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'chicken-curry');
insert into public.recipe_variation_rules (recipe_id, rule_type, condition, action, note) values
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 'spice', '{"member_age_group": "child"}'::jsonb, '{"reduce": {"kashmiri chilli powder": 0.5}}'::jsonb, 'Kashmiri chilli is mild in heat; halve it for young children.'),
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 'equipment', '{"have_equipment": "pressure_cooker"}'::jsonb, '{"at_step": 5, "method": "pressure_cook", "water_ml": 150, "whistles": 3}'::jsonb, 'Pressure-cook for 3 whistles with less water instead of simmering; still check that the chicken is cooked through.');

