insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('dal-tadka', 'Dal Tadka', '{"en": "Dal Tadka", "hi": "दाल तड़का", "hi-Latn": "Dal Tadka"}'::jsonb, 'Everyday arhar dal, pressure-cooked soft and finished with a ghee tadka of cumin, garlic, onion and tomato.', '{"hi": "रोज़ की अरहर दाल, कुकर में नरम पकी, ऊपर से जीरा, लहसुन, प्याज़ और टमाटर का घी वाला तड़का।", "hi-Latn": "Roz ki arhar daal, cooker mein naram paki, upar se jeera, lahsun, pyaaz aur tamatar ka ghee wala tadka."}'::jsonb, 'generic_north', 'main', 'veg', 4, 25, 25, 2, 2, array['pressure_cooker', 'kadai']::text[], array['comforting', 'high_protein']::text[], '{"acid": 0.3, "crunch": 0, "heat": 0.3, "rich": 0.5, "starch": 0.4, "sweet": 0}'::jsonb, array['dal']::text[], 'curated', 'draft', false)
