insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 1, 'Rinse the dal 2 to 3 times until the water runs almost clear, then soak in fresh water.', '{"en": "Rinse the dal 2 to 3 times until the water runs almost clear, then soak in fresh water.", "hi": {"look": "धोने का पानी लगभग साफ़ आए।", "text": "दाल को 2-3 बार धोएँ जब तक पानी लगभग साफ़ न हो जाए, फिर ताज़े पानी में भिगो दें।"}, "hi-Latn": {"look": "Dhone ka paani lagbhag saaf aaye.", "text": "Daal ko 2-3 baar dhoyein jab tak paani lagbhag saaf na ho jaaye, phir taaze paani mein bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 1200, true, null, 'Soaking is optional but makes the dal cook softer and faster.', '{"en": "Soaking is optional but makes the dal cook softer and faster.", "look": "The rinse water runs almost clear."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 2, 'Drain and pressure-cook the dal with 600 ml water and the turmeric on medium heat.', '{"en": "Drain and pressure-cook the dal with 600 ml water and the turmeric on medium heat.", "hi": {"sound": "सीटियाँ गिनें; फिर प्रेशर अपने आप उतरने दें।", "text": "पानी निकालें और दाल को 600 ml पानी और हल्दी के साथ मध्यम आँच पर कुकर में पकाएँ।", "touch": "चम्मच से दबाने पर दाल पूरी तरह मसल जाए।"}, "hi-Latn": {"sound": "Seetiyaan ginein; phir pressure apne aap utarne dein.", "text": "Paani nikaalein aur daal ko 600 ml paani aur haldi ke saath madhyam aanch par cooker mein pakaayein.", "touch": "Chammach se dabaane par daal poori tarah masal jaaye."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 900, false, 4, 'Let the pressure drop by itself. The dal should mash completely when pressed with a spoon.', '{"en": "Let the pressure drop by itself. The dal should mash completely when pressed with a spoon.", "heat": "medium", "sound": "Count the whistles; then let the pressure drop by itself.", "touch": "The dal mashes completely when pressed with a spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 3, 'Whisk the dal smooth, add the salt and hot water until it pours like thick soup, and simmer.', '{"en": "Whisk the dal smooth, add the salt and hot water until it pours like thick soup, and simmer.", "hi": {"avoid": "बीच-बीच में चलाएँ; गाढ़ी होते-होते दाल तले में लगती है।", "look": "गाढ़े सूप की तरह बहे और धीरे-धीरे उबले।", "text": "दाल को फेंटकर चिकना करें, नमक और गरम पानी डालें जब तक गाढ़े सूप जैसी न हो जाए, और धीमी आँच पर उबालें।"}, "hi-Latn": {"avoid": "Beech-beech mein chalaayein; gaadhi hote-hote daal tale mein lagti hai.", "look": "Gaadhe soup ki tarah bahe aur dheere-dheere ubale.", "text": "Daal ko phent kar chikna karein, namak aur garam paani daalein jab tak gaadhe soup jaisi na ho jaaye, aur dheemi aanch par ubaalein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, false, null, 'It pours like thick soup and bubbles gently. Stir now and then; dal sticks to the bottom as it thickens.', '{"avoid": "Stir now and then; dal sticks to the bottom as it thickens.", "en": "It pours like thick soup and bubbles gently. Stir now and then; dal sticks to the bottom as it thickens.", "heat": "low", "look": "It pours like thick soup and bubbles gently."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 4, 'For the tadka heat the ghee in a kadai. Add cumin, hing and garlic; when the garlic is golden add onion, ginger and green chilli and cook until the onion is light golden. Add the tomato and chilli powder and cook until soft.', '{"en": "For the tadka heat the ghee in a kadai. Add cumin, hing and garlic; when the garlic is golden add onion, ginger and green chilli and cook until the onion is light golden. Add the tomato and chilli powder and cook until soft.", "hi": {"avoid": "लहसुन भूरा न होने दें, वरना कड़वा हो जाएगा।", "branch": "मिर्च वाला तड़का डालने से पहले बच्चे की दाल निकाल लें; उसमें बस थोड़ा घी और जीरा डालें", "look": "लहसुन सुनहरा हो, टमाटर गल जाए और किनारों पर घी चमके।", "smell": "भुने लहसुन और जीरे की ख़ुशबू।", "sound": "घी में पड़ते ही जीरा चटकने लगे।", "text": "तड़के के लिए कड़ाही में घी गरम करें। जीरा, हींग और लहसुन डालें; लहसुन सुनहरा हो तो प्याज़, अदरक और हरी मिर्च डालकर प्याज़ हल्का सुनहरा होने तक पकाएँ। टमाटर और मिर्च पाउडर डालकर नरम होने तक पकाएँ।"}, "hi-Latn": {"avoid": "Lahsun bhoora na hone dein, warna kadva ho jaayega.", "branch": "Mirch wala tadka daalne se pehle bachche ki daal nikaal lein; usmein bas thoda ghee aur jeera daalein", "look": "Lahsun sunehra ho, tamatar gal jaaye aur kinaaron par ghee chamke.", "smell": "Bhune lahsun aur jeere ki khushboo.", "sound": "Ghee mein padte hi jeera chatakne lage.", "text": "Tadke ke liye kadaahi mein ghee garam karein. Jeera, hing aur lahsun daalein; lahsun sunehra ho to pyaaz, adrak aur hari mirch daalkar pyaaz halka sunehra hone tak pakaayein. Tamatar aur mirch powder daalkar naram hone tak pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 420, false, null, 'Garlic should be golden, not brown. The tomato breaks down and the ghee shines at the edges.', '{"avoid": "Don''t let the garlic go brown: it turns bitter.", "en": "Garlic should be golden, not brown. The tomato breaks down and the ghee shines at the edges.", "heat": "medium", "look": "Garlic is golden, the tomato has broken down and the ghee shines at the edges.", "smell": "Nutty garlic and toasted cumin.", "sound": "Cumin crackles as soon as it hits the ghee."}'::jsonb, '{"action": "Take out the child''s dal before adding the chilli tadka; give it a little ghee and cumin only", "age_group": "child"}'::jsonb, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 5, 'Pour the tadka into the dal, simmer 2 minutes, then add coriander leaves and lemon juice.', '{"en": "Pour the tadka into the dal, simmer 2 minutes, then add coriander leaves and lemon juice.", "hi": {"taste": "नींबू डालने के बाद नमक और खटास चखकर देखें।", "text": "तड़का दाल में डालें, 2 मिनट उबालें, फिर हरा धनिया और नींबू का रस डालें।"}, "hi-Latn": {"taste": "Nimbu daalne ke baad namak aur khataas chakh kar dekhein.", "text": "Tadka daal mein daalein, 2 minute ubaalein, phir hara dhaniya aur nimbu ka ras daalein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 120, false, null, 'Taste for salt and sourness after the lemon.', '{"en": "Taste for salt and sourness after the lemon.", "heat": "low", "taste": "Taste for salt and sourness after the lemon."}'::jsonb, null, null)
