insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'egg-bhurji'), 1, 'Beat the eggs with a pinch of the salt.', '{"en": "Beat the eggs with a pinch of the salt.", "hi": {"look": "ज़र्दी और सफ़ेदी पूरी मिल जाए, थोड़ा झाग आ जाए।", "text": "अंडों में चुटकी भर नमक डालकर फेंटें।"}, "hi-Latn": {"look": "Zardi aur safedi poori mil jaaye, thoda jhaag aa jaaye.", "text": "Andon mein chutki bhar namak daalkar phentein."}}'::jsonb, null, 60, false, null, 'The yolks and whites are fully mixed, a little frothy.', '{"en": "The yolks and whites are fully mixed, a little frothy.", "look": "The yolks and whites are fully mixed, a little frothy."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'egg-bhurji'), 2, 'Heat the oil in a kadai and cook the onion until soft. Add the green chilli and ginger, then the tomato, and cook until the tomato is soft.', '{"en": "Heat the oil in a kadai and cook the onion until soft. Add the green chilli and ginger, then the tomato, and cook until the tomato is soft.", "hi": {"look": "प्याज़ नरम और पारदर्शी हो, टमाटर दबाने पर गल जाए।", "smell": "प्याज़ की मीठी ख़ुशबू, कच्ची महक नहीं।", "text": "कड़ाही में तेल गरम करें और प्याज़ नरम होने तक पकाएँ। हरी मिर्च और अदरक डालें, फिर टमाटर, और टमाटर नरम होने तक पकाएँ।"}, "hi-Latn": {"look": "Pyaaz naram aur paardarshi ho, tamatar dabaane par gal jaaye.", "smell": "Pyaaz ki meethi khushboo, kachchi mehak nahi.", "text": "Kadaahi mein tel garam karein aur pyaaz naram hone tak pakaayein. Hari mirch aur adrak daalein, phir tamatar, aur tamatar naram hone tak pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 300, false, null, 'The tomato breaks down when pressed with the spoon.', '{"en": "The tomato breaks down when pressed with the spoon.", "heat": "medium", "look": "The onion is soft and see-through, the tomato breaks down when pressed.", "smell": "Sweet onion, no raw smell."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'egg-bhurji'), 3, 'Add turmeric, chilli powder, pav bhaji masala and the rest of the salt and stir for 30 seconds.', '{"en": "Add turmeric, chilli powder, pav bhaji masala and the rest of the salt and stir for 30 seconds.", "hi": {"avoid": "बस 30 सेकंड: सूखी कड़ाही में मसाले जल्दी जलते हैं।", "smell": "मसाले भुने हुए महकें, कच्चे नहीं।", "text": "हल्दी, मिर्च पाउडर, पाव भाजी मसाला और बचा नमक डालकर 30 सेकंड चलाएँ।"}, "hi-Latn": {"avoid": "Bas 30 second: sookhi kadaahi mein masaale jaldi jalte hain.", "smell": "Masaale bhune hue mehkein, kachche nahi.", "text": "Haldi, mirch powder, pav bhaji masala aur bacha namak daalkar 30 second chalaayein."}}'::jsonb, null, 60, false, null, 'The spices smell toasted, not raw. Just 30 seconds: spices burn quickly in a dry pan.', '{"avoid": "Just 30 seconds: spices burn quickly in a dry pan.", "en": "The spices smell toasted, not raw. Just 30 seconds: spices burn quickly in a dry pan.", "heat": "medium", "smell": "The spices smell toasted, not raw."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'egg-bhurji'), 4, 'Lower the heat and pour in the eggs. Leave them for 20 seconds, then scramble, scraping the bottom, until fully set.', '{"en": "Lower the heat and pour in the eggs. Leave them for 20 seconds, then scramble, scraping the bottom, until fully set.", "hi": {"avoid": "चमकते गीले अंडे पर मत रुकें: पूरा पकने तक पकाएँ।", "look": "नरम, रसीले दाने, कहीं भी बहता अंडा नहीं।", "safety": "अंडा पूरा पकने तक पकाएँ, कोई गीला या बहता हिस्सा न रहे, ख़ासकर बच्चों, बुज़ुर्गों और गर्भवती महिलाओं के लिए।", "text": "आँच धीमी करें और अंडे डालें। 20 सेकंड छोड़ दें, फिर तले से खुरचते हुए तब तक चलाएँ जब तक अंडा पूरा पक न जाए।", "touch": "अंडा दबाने पर कुछ गीला न निकले।"}, "hi-Latn": {"avoid": "Chamakte geele ande par mat rukein: poora pakne tak pakaayein.", "look": "Naram, raseele daane, kahin bhi behta anda nahi.", "safety": "Anda poora pakne tak pakaayein, koi geela ya behta hissa na rahe, khaaskar bachchon, buzurgon aur garbhvati mahilaon ke liye.", "text": "Aanch dheemi karein aur ande daalein. 20 second chhod dein, phir tale se khurachte hue tab tak chalaayein jab tak anda poora pak na jaaye.", "touch": "Anda dabaane par kuch geela na nikle."}}'::jsonb, null, 240, false, null, 'Soft, moist curds with no runny egg left.', '{"avoid": "Don''t stop at shiny wet egg: cook until fully set.", "en": "Soft, moist curds with no runny egg left.", "heat": "low", "look": "Soft, moist curds with no runny egg left.", "touch": "Nothing wet runs out when you press the egg."}'::jsonb, null, 'Cook until the egg is fully set with no wet or runny parts, especially for children, elders or anyone pregnant.'),
  ((select id from public.recipes where household_id is null and slug = 'egg-bhurji'), 5, 'Add the coriander leaves and serve hot.', '{"en": "Add the coriander leaves and serve hot.", "hi": {"look": "परोसते समय भाप निकल रही हो।", "text": "हरा धनिया डालें और गरम-गरम परोसें।"}, "hi-Latn": {"look": "Parosate samay bhaap nikal rahi ho.", "text": "Hara dhaniya daalein aur garam-garam parosein."}}'::jsonb, null, 60, false, null, 'Steaming hot when served.', '{"en": "Steaming hot when served.", "look": "Steaming hot when served."}'::jsonb, null, null)
