  ('jeera-aloo', 'Jeera Aloo', '{"en": "Jeera Aloo", "hi": "जीरा आलू", "hi-Latn": "Jeera Aloo"}'::jsonb, 'Boiled potatoes tossed in a cumin tadka with turmeric, chilli and a squeeze of amchur. Quick, dry and loved by children.', '{"hi": "उबले आलू जीरे के तड़के में, हल्दी, मिर्च और थोड़े आमचूर के साथ। जल्दी बनते हैं, सूखे, और बच्चों को पसंद।", "hi-Latn": "Ubale aloo jeere ke tadke mein, haldi, mirch aur thode amchur ke saath. Jaldi bante hain, sookhe, aur bachchon ko pasand."}'::jsonb, 'generic_north', 'side', 'vegan', 4, 5, 20, 1, 2, array['pressure_cooker', 'kadai']::text[], array['quick', 'kids_friendly']::text[], '{"acid": 0.3, "crunch": 0.3, "heat": 0.3, "rich": 0.3, "starch": 0.9, "sweet": 0}'::jsonb, array['sabzi']::text[], 'curated', 'draft', false)
