insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'jeera-aloo'), 1, 'Pressure-cook the whole potatoes with water to cover.', '{"en": "Pressure-cook the whole potatoes with water to cover.", "hi": {"sound": "दो सीटी गिनें, फिर प्रेशर अपने आप उतरने दें।", "text": "साबुत आलू को डूबने लायक पानी में कुकर में उबालें।", "touch": "चाकू आसानी से अंदर जाए पर आलू अपना आकार न छोड़े।"}, "hi-Latn": {"sound": "Do seeti ginein, phir pressure apne aap utarne dein.", "text": "Saabut aloo ko doobne laayak paani mein cooker mein ubaalein.", "touch": "Chaaku aasaani se andar jaaye par aloo apna aakaar na chhode."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 600, false, 2, 'Let the pressure drop by itself. A knife should slide in easily but the potato should still hold its shape.', '{"en": "Let the pressure drop by itself. A knife should slide in easily but the potato should still hold its shape.", "heat": "medium", "sound": "Count two whistles, then let the pressure drop by itself.", "touch": "A knife slides in easily but the potato still holds its shape."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'jeera-aloo'), 2, 'Peel the potatoes once cool enough to touch and cut into bite-sized cubes.', '{"en": "Peel the potatoes once cool enough to touch and cut into bite-sized cubes.", "hi": {"look": "बराबर छोटे टुकड़े, ताकि सब एक साथ सिकें।", "text": "आलू छूने लायक ठंडे हों तो छीलकर छोटे टुकड़ों में काटें।", "touch": "छीलने से पहले हाथ में पकड़ने लायक ठंडे हों।"}, "hi-Latn": {"look": "Barabar chhote tukde, taaki sab ek saath sikein.", "text": "Aloo chhoone laayak thande hon to chheel kar chhote tukdon mein kaatein.", "touch": "Chheelne se pehle haath mein pakadne laayak thande hon."}}'::jsonb, null, 300, false, null, 'Even, bite-sized cubes so they brown together. Cool enough to hold before peeling.', '{"en": "Even, bite-sized cubes so they brown together. Cool enough to hold before peeling.", "look": "Even, bite-sized cubes so they brown together.", "touch": "Cool enough to hold before peeling."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'jeera-aloo'), 3, 'Heat the oil in a kadai. Add cumin, then hing, green chilli and ginger and stir for 30 seconds.', '{"en": "Heat the oil in a kadai. Add cumin, then hing, green chilli and ginger and stir for 30 seconds.", "hi": {"avoid": "अगर जीरा काला हो जाए तो दोबारा शुरू करें: वरना कड़वा लगेगा।", "look": "जीरा एक रंग गहरा हो जाए।", "smell": "भुने जीरे की सोंधी ख़ुशबू।", "sound": "जीरा डालते ही चटकने लगे।", "text": "कड़ाही में तेल गरम करें। जीरा डालें, फिर हींग, हरी मिर्च और अदरक डालकर 30 सेकंड चलाएँ।"}, "hi-Latn": {"avoid": "Agar jeera kaala ho jaaye to dobaara shuru karein: warna kadva lagega.", "look": "Jeera ek rang gehra ho jaaye.", "smell": "Bhune jeere ki sondhi khushboo.", "sound": "Jeera daalte hi chatakne lage.", "text": "Kadaahi mein tel garam karein. Jeera daalein, phir hing, hari mirch aur adrak daalkar 30 second chalaayein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'Cumin sizzles and darkens one shade. If it turns black, start again.', '{"avoid": "If the cumin turns black, start again: it will taste bitter.", "en": "Cumin sizzles and darkens one shade. If it turns black, start again.", "heat": "medium", "look": "Cumin darkens one shade.", "smell": "Toasty, nutty cumin.", "sound": "The cumin sizzles and crackles straight away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'jeera-aloo'), 4, 'Add turmeric, chilli powder and coriander powder, then immediately the potatoes and salt. Toss on medium heat.', '{"en": "Add turmeric, chilli powder and coriander powder, then immediately the potatoes and salt. Toss on medium heat.", "hi": {"avoid": "हल्के हाथ से मिलाएँ ताकि आलू टूटकर भरता न बन जाएँ।", "look": "आलू के किनारे सुनहरे और थोड़े कुरकुरे हो जाएँ।", "sound": "मिलाते समय लगातार छन-छन।", "text": "हल्दी, मिर्च पाउडर और धनिया पाउडर डालें, फिर तुरंत आलू और नमक डालें। मध्यम आँच पर उछालते हुए मिलाएँ।"}, "hi-Latn": {"avoid": "Halke haath se milaayein taaki aloo toot kar bharta na ban jaayein.", "look": "Aloo ke kinaare sunehre aur thode kurkure ho jaayein.", "sound": "Milaate samay lagaataar chhan-chhan.", "text": "Haldi, mirch powder aur dhaniya powder daalein, phir turant aloo aur namak daalein. Madhyam aanch par uchhaalte hue milaayein."}}'::jsonb, (select id from public.techniques where slug = 'shallow_fry'), 360, true, null, 'The edges of the potatoes turn golden and slightly crisp.', '{"avoid": "Toss gently so the potatoes don''t break into mash.", "en": "The edges of the potatoes turn golden and slightly crisp.", "heat": "medium", "look": "The edges turn golden and slightly crisp.", "sound": "A steady sizzle as you toss."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'jeera-aloo'), 5, 'Sprinkle amchur and coriander leaves, toss once and serve.', '{"en": "Sprinkle amchur and coriander leaves, toss once and serve.", "hi": {"taste": "एक टुकड़ा चखकर नमक और खटास देखें।", "text": "आमचूर और हरा धनिया छिड़कें, एक बार मिलाएँ और परोसें।"}, "hi-Latn": {"taste": "Ek tukda chakh kar namak aur khataas dekhein.", "text": "Amchur aur hara dhaniya chhidkein, ek baar milaayein aur parosein."}}'::jsonb, null, 60, false, null, 'Taste one piece for salt and sourness.', '{"en": "Taste one piece for salt and sourness.", "taste": "Taste one piece for salt and sourness."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
