  ((select id from public.recipes where household_id is null and slug = 'jeera-aloo'), 'equipment', '{"missing_equipment": "pressure_cooker"}'::jsonb, '{"at_step": 1, "method": "boil", "minutes": 20}'::jsonb, 'Boil in a covered pot for about 20 minutes until tender.'),
  ((select id from public.recipes where household_id is null and slug = 'jeera-aloo'), 'spice', '{"member_age_group": "child"}'::jsonb, '{"omit": ["green chilli", "red chilli powder"]}'::jsonb, 'Leave out the chillies; the cumin and amchur carry the flavour.');

-- Recipe: jeera-rice (draft, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('jeera-rice', 'Jeera Rice', '{"en": "Jeera Rice", "hi": "जीरा राइस", "hi-Latn": "Jeera Rice"}'::jsonb, 'Fluffy rice with a ghee and cumin tadka. Rinse, soak, then cook with the right water, so every grain stays separate.', '{"hi": "घी और जीरे के तड़के वाले खिले-खिले चावल। धोएँ, भिगोएँ और सही पानी में पकाएँ, ताकि हर दाना अलग रहे।", "hi-Latn": "Ghee aur jeere ke tadke waale khile-khile chaawal. Dhoyein, bhigoyein aur sahi paani mein pakaayein, taaki har daana alag rahe."}'::jsonb, 'generic_north', 'component', 'veg', 2, 20, 15, 1, 1, array['pressure_cooker']::text[], array['basics', 'quick', 'kids_friendly']::text[], '{"acid": 0, "crunch": 0, "heat": 0, "rich": 0.3, "starch": 1, "sweet": 0}'::jsonb, array['grain']::text[], 'curated', 'draft', false)
