insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'jeera-rice'), 1, 'Rinse the rice two or three times and soak it in water.', '{"en": "Rinse the rice two or three times and soak it in water.", "hi": {"look": "धोने का पानी लगभग साफ़ हो जाए।", "text": "चावल को दो-तीन बार धोएँ और पानी में भिगो दें।"}, "hi-Latn": {"look": "Dhone ka paani lagbhag saaf ho jaaye.", "text": "Chaawal ko do-teen baar dhoyein aur paani mein bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 900, true, null, 'The rinse water runs almost clear.', '{"en": "The rinse water runs almost clear.", "look": "The rinse water runs almost clear."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'jeera-rice'), 2, 'Heat ghee in the cooker. Add cumin and the bay leaf.', '{"en": "Heat ghee in the cooker. Add cumin and the bay leaf.", "hi": {"smell": "भुने जीरे की ख़ुशबू।", "sound": "जीरा चटकने लगे।", "text": "कुकर में घी गरम करें। जीरा और तेज पत्ता डालें।"}, "hi-Latn": {"smell": "Bhune jeere ki khushboo.", "sound": "Jeera chatakne lage.", "text": "Cooker mein ghee garam karein. Jeera aur tej patta daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 30, false, null, 'The cumin crackles. Toasty cumin.', '{"en": "The cumin crackles. Toasty cumin.", "heat": "medium", "smell": "Toasty cumin.", "sound": "The cumin crackles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'jeera-rice'), 3, 'Drain the rice and stir it gently in the ghee for a minute. Add salt and one and a half katori of water for each katori of rice. Close and cook for one whistle.', '{"en": "Drain the rice and stir it gently in the ghee for a minute. Add salt and one and a half katori of water for each katori of rice. Close and cook for one whistle.", "hi": {"look": "बंद करने से पहले पानी चावल से लगभग एक पोर ऊपर हो।", "sound": "पहली सीटी पर आँच बंद करें।", "text": "चावल का पानी निकालें और घी में एक मिनट धीरे से चलाएँ। नमक और हर कटोरी चावल पर डेढ़ कटोरी पानी डालें। बंद करके एक सीटी लगाएँ।"}, "hi-Latn": {"look": "Band karne se pehle paani chaawal se lagbhag ek por upar ho.", "sound": "Pehli seeti par aanch band karein.", "text": "Chaawal ka paani nikaalein aur ghee mein ek minute dheere se chalaayein. Namak aur har katori chaawal par dedh katori paani daalein. Band karke ek seeti lagaayein."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 480, false, 1, 'The water should be about one finger joint above the rice before closing. Turn off at the first whistle.', '{"en": "The water should be about one finger joint above the rice before closing. Turn off at the first whistle.", "heat": "medium", "look": "The water should be about one finger joint above the rice before closing.", "sound": "Turn off at the first whistle."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'jeera-rice'), 4, 'Let the pressure drop by itself, then wait five more minutes and fluff with a fork.', '{"en": "Let the pressure drop by itself, then wait five more minutes and fluff with a fork.", "hi": {"avoid": "धीरे चलाएँ; चम्मच से दाने टूटते हैं।", "look": "लंबे, अलग-अलग दाने और नीचे पानी न बचे।", "text": "प्रेशर अपने आप उतरने दें, फिर पाँच मिनट और रुककर काँटे से हल्के से खिलाएँ।"}, "hi-Latn": {"avoid": "Dheere chalaayein; chammach se daane toot-te hain.", "look": "Lambe, alag-alag daane aur neeche paani na bache.", "text": "Pressure apne aap utarne dein, phir paanch minute aur ruk kar kaante se halke se khilaayein."}}'::jsonb, null, 300, true, null, 'Long, separate grains with no water left at the bottom. Stir gently; a spoon breaks the grains.', '{"avoid": "Stir gently; a spoon breaks the grains.", "en": "Long, separate grains with no water left at the bottom. Stir gently; a spoon breaks the grains.", "look": "Long, separate grains with no water left at the bottom."}'::jsonb, null, null)
