insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('kadhi-pakora', 'Kadhi Pakora', '{"en": "Kadhi Pakora", "hi": "कढ़ी पकौड़ा", "hi-Latn": "Kadhi Pakora"}'::jsonb, 'Tangy curd and besan kadhi simmered slowly, with soft onion pakoras and a ghee tadka of cumin, methi dana and red chilli.', '{"hi": "धीमी आँच पर पकी खट्टी दही-बेसन की कढ़ी, नरम प्याज़ के पकौड़े और जीरा, मेथी दाना, लाल मिर्च का घी वाला तड़का।", "hi-Latn": "Dheemi aanch par paki khatti dahi-besan ki kadhi, naram pyaaz ke pakode aur jeera, methi daana, laal mirch ka ghee wala tadka."}'::jsonb, 'punjabi', 'main', 'veg', 4, 15, 45, 3, 2, array['kadai']::text[], array['comforting']::text[], '{"acid": 0.7, "crunch": 0.3, "heat": 0.3, "rich": 0.5, "starch": 0.4, "sweet": 0}'::jsonb, array['dal', 'dairy']::text[], 'curated', 'draft', false)
