insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 1, 'In a big bowl whisk the curd, 6 chammach besan, turmeric, red chilli powder and salt until completely smooth. Add 900 ml water and whisk again.', '{"en": "In a big bowl whisk the curd, 6 chammach besan, turmeric, red chilli powder and salt until completely smooth. Add 900 ml water and whisk again.", "hi": {"look": "बिल्कुल गाँठ न हो, और छाछ जितना पतला हो।", "text": "बड़े बर्तन में दही, 6 चम्मच बेसन, हल्दी, लाल मिर्च पाउडर और नमक पूरी तरह चिकना होने तक फेंटें। 900 ml पानी डालकर फिर फेंटें।"}, "hi-Latn": {"look": "Bilkul gaanth na ho, aur chhaachh jitna patla ho.", "text": "Bade bartan mein dahi, 6 chammach besan, haldi, laal mirch powder aur namak poori tarah chikna hone tak phentein. 900 ml paani daalkar phir phentein."}}'::jsonb, (select id from public.techniques where slug = 'batter'), 180, false, null, 'No lumps at all, and as thin as buttermilk.', '{"en": "No lumps at all, and as thin as buttermilk.", "look": "No lumps at all, and as thin as buttermilk."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 2, 'Pour into the kadai with the grated ginger. Bring to a boil on medium heat, stirring all the time.', '{"en": "Pour into the kadai with the grated ginger. Bring to a boil on medium heat, stirring all the time.", "hi": {"avoid": "पहला उबाल आने तक चलाते रहें, वरना दही फट सकता है।", "look": "हर तरफ़ से छोटे बुलबुले उठने लगें।", "text": "कसे अदरक के साथ कड़ाही में डालें। मध्यम आँच पर लगातार चलाते हुए उबाल आने दें।"}, "hi-Latn": {"avoid": "Pehla ubaal aane tak chalaate rahein, warna dahi phat sakta hai.", "look": "Har taraf se chhote bulbule uthne lagein.", "text": "Kase adrak ke saath kadaahi mein daalein. Madhyam aanch par lagaataar chalaate hue ubaal aane dein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 480, false, null, 'Keep stirring until the first boil. If you stop, the curd can split.', '{"avoid": "Keep stirring until the first boil, or the curd can split.", "en": "Keep stirring until the first boil. If you stop, the curd can split.", "heat": "medium", "look": "Small bubbles start rising all over."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 3, 'Lower the heat and let the kadhi simmer, stirring every few minutes.', '{"en": "Lower the heat and let the kadhi simmer, stirring every few minutes.", "hi": {"look": "कढ़ी चम्मच के पीछे लिपटने लगे।", "smell": "कच्चे बेसन की महक चली जाए।", "text": "आँच धीमी करें और कढ़ी को पकने दें, हर कुछ मिनट में चलाते रहें।"}, "hi-Latn": {"look": "Kadhi chammach ke peechhe lipatne lage.", "smell": "Kachche besan ki mehak chali jaaye.", "text": "Aanch dheemi karein aur kadhi ko pakne dein, har kuch minute mein chalaate rahein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 1500, true, null, 'It thickens enough to coat the back of a spoon, and the raw besan smell is gone.', '{"en": "It thickens enough to coat the back of a spoon, and the raw besan smell is gone.", "heat": "low", "look": "It coats the back of a spoon.", "smell": "The raw besan smell is gone."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 4, 'Meanwhile make the pakora batter. Mix 2 katori besan with the sliced onion, green chilli, ajwain, a little salt and the soda, adding about 100 ml water slowly. Beat for 2 minutes.', '{"en": "Meanwhile make the pakora batter. Mix 2 katori besan with the sliced onion, green chilli, ajwain, a little salt and the soda, adding about 100 ml water slowly. Beat for 2 minutes.", "hi": {"look": "घोल की एक बूँद पानी की कटोरी में तैर जाए।", "text": "इस बीच पकौड़ों का घोल बनाएँ। 2 कटोरी बेसन में कटा प्याज़, हरी मिर्च, अजवाइन, थोड़ा नमक और सोडा मिलाएँ, लगभग 100 ml पानी धीरे-धीरे डालें। 2 मिनट फेंटें।", "touch": "इतना गाढ़ा कि चम्मच से गोले की तरह गिरे।"}, "hi-Latn": {"look": "Ghol ki ek boond paani ki katori mein tair jaaye.", "text": "Is beech pakodon ka ghol banaayein. 2 katori besan mein kata pyaaz, hari mirch, ajwain, thoda namak aur soda milaayein, lagbhag 100 ml paani dheere-dheere daalein. 2 minute phentein.", "touch": "Itna gaadha ki chammach se gole ki tarah gire."}}'::jsonb, (select id from public.techniques where slug = 'batter'), 240, false, null, 'Thick enough to drop from a spoon in a blob. A drop of batter floats in a bowl of water.', '{"en": "Thick enough to drop from a spoon in a blob. A drop of batter floats in a bowl of water.", "look": "A drop of batter floats in a bowl of water.", "touch": "Thick enough to drop from a spoon in a blob."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 5, 'Heat the oil in a second pan on medium. Drop small spoonfuls of batter and fry in batches until golden all over.', '{"en": "Heat the oil in a second pan on medium. Drop small spoonfuls of batter and fry in batches until golden all over.", "hi": {"avoid": "तेल से धुआँ निकले तो आँच कम करें: वरना बाहर भूरा हो जाएगा और अंदर कच्चा रहेगा।", "look": "पकौड़े ऊपर तैर आएँ और हर तरफ़ से सुनहरे हो जाएँ।", "safety": "बच्चों को गरम तेल से दूर रखें। घोल तेल के पास से धीरे से डालें ताकि छींटे न पड़ें, और गरम तेल में कभी पानी न टपकने दें।", "sound": "हर पकौड़े के आस-पास तेज़, लगातार बुलबुले; पकने पर आवाज़ धीमी हो जाए।", "text": "दूसरी कड़ाही में मध्यम आँच पर तेल गरम करें। घोल के छोटे-छोटे चम्मच डालें और थोड़े-थोड़े करके हर तरफ़ से सुनहरा होने तक तलें।"}, "hi-Latn": {"avoid": "Tel se dhuaan nikle to aanch kam karein: warna bahar bhoora ho jaayega aur andar kachcha rahega.", "look": "Pakode upar tair aayein aur har taraf se sunehre ho jaayein.", "safety": "Bachchon ko garam tel se door rakhein. Ghol tel ke paas se dheere se daalein taaki chheente na padein, aur garam tel mein kabhi paani na tapakne dein.", "sound": "Har pakode ke aas-paas tez, lagaataar bulbule; pakne par awaaz dheemi ho jaaye.", "text": "Doosri kadaahi mein madhyam aanch par tel garam karein. Ghol ke chhote-chhote chammach daalein aur thode-thode karke har taraf se sunehra hone tak talein."}}'::jsonb, (select id from public.techniques where slug = 'deep_fry'), 720, false, null, 'The pakoras rise to the top and turn golden in about 4 minutes per batch.', '{"avoid": "If the oil smokes, turn it down: the outside browns before the inside cooks.", "en": "The pakoras rise to the top and turn golden in about 4 minutes per batch.", "heat": "medium", "look": "The pakoras rise to the top and turn golden all over.", "sound": "Fast, steady bubbling around each pakora; it quietens as they cook through."}'::jsonb, null, 'Keep children away from the hot oil. Slide the batter in close to the oil so it does not splash, and never let water drip into hot oil.'),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 6, 'Add the pakoras to the kadhi and simmer for 5 more minutes so they soak it up.', '{"en": "Add the pakoras to the kadhi and simmer for 5 more minutes so they soak it up.", "hi": {"text": "पकौड़े कढ़ी में डालें और 5 मिनट और पकाएँ ताकि वे कढ़ी सोख लें।", "touch": "पकौड़े नरम हो जाएँ और कढ़ी सोख लें।"}, "hi-Latn": {"text": "Pakode kadhi mein daalein aur 5 minute aur pakaayein taaki ve kadhi sokh lein.", "touch": "Pakode naram ho jaayein aur kadhi sokh lein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, true, null, 'The pakoras turn soft and soak up the kadhi.', '{"en": "The pakoras turn soft and soak up the kadhi.", "heat": "low", "touch": "The pakoras turn soft and soak up the kadhi."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 7, 'For the tadka, heat the ghee. Add cumin, methi dana, dry red chillies and hing. Turn off the heat, add Kashmiri chilli powder and pour over the kadhi at once.', '{"en": "For the tadka, heat the ghee. Add cumin, methi dana, dry red chillies and hing. Turn off the heat, add Kashmiri chilli powder and pour over the kadhi at once.", "hi": {"avoid": "मिर्च पाउडर आँच बंद करके डालें ताकि लाल रहे, काला नहीं।", "branch": "मिर्च वाला तड़का डालने से पहले बच्चे का हिस्सा निकाल लें", "look": "कुछ सेकंड में जीरा एक रंग गहरा हो; मिर्च पाउडर लाल हो जाए।", "sound": "तड़का कढ़ी पर पड़ते ही ज़ोर की छन्न।", "text": "तड़के के लिए घी गरम करें। जीरा, मेथी दाना, सूखी लाल मिर्च और हींग डालें। आँच बंद करें, कश्मीरी मिर्च पाउडर डालें और तुरंत कढ़ी पर डाल दें।"}, "hi-Latn": {"avoid": "Mirch powder aanch band karke daalein taaki laal rahe, kaala nahi.", "branch": "Mirch wala tadka daalne se pehle bachche ka hissa nikaal lein", "look": "Kuch second mein jeera ek rang gehra ho; mirch powder laal ho jaaye.", "sound": "Tadka kadhi par padte hi zor ki chhann.", "text": "Tadke ke liye ghee garam karein. Jeera, methi daana, sookhi laal mirch aur hing daalein. Aanch band karein, Kashmiri mirch powder daalein aur turant kadhi par daal dein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'Cumin darkens one shade in a few seconds. Add the chilli powder off the heat so it turns red, not black.', '{"avoid": "Add the chilli powder off the heat so it turns red, not black.", "en": "Cumin darkens one shade in a few seconds. Add the chilli powder off the heat so it turns red, not black.", "heat": "medium", "look": "Cumin darkens one shade in a few seconds; the chilli powder turns red.", "sound": "A loud sizzle as the tadka hits the kadhi."}'::jsonb, '{"action": "Take out the child''s portion before pouring the chilli tadka", "age_group": "child"}'::jsonb, null)
