insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 1, 'Put the poha in a sieve and rinse under running water for a few seconds, 2 to 3 times. Do not soak. Sprinkle turmeric, salt and sugar, toss gently and leave for 5 minutes.', '{"en": "Put the poha in a sieve and rinse under running water for a few seconds, 2 to 3 times. Do not soak. Sprinkle turmeric, salt and sugar, toss gently and leave for 5 minutes.", "hi": {"avoid": "भिगोएँ नहीं: गीला पोहा गोला बन जाता है।", "text": "पोहा छलनी में डालकर बहते पानी में कुछ सेकंड, 2-3 बार धोएँ। भिगोएँ नहीं। हल्दी, नमक और चीनी छिड़कें, हल्के से मिलाएँ और 5 मिनट छोड़ दें।", "touch": "दो उँगलियों में दबाने पर पोहा आसानी से मसल जाए, पर गीला या गला न हो।"}, "hi-Latn": {"avoid": "Bhigoyein nahi: geela poha gola ban jaata hai.", "text": "Poha chhalni mein daalkar behte paani mein kuch second, 2-3 baar dhoyein. Bhigoyein nahi. Haldi, namak aur cheeni chhidkein, halke se milaayein aur 5 minute chhod dein.", "touch": "Do ungliyon mein dabaane par poha aasaani se masal jaaye, par geela ya gala na ho."}}'::jsonb, null, 300, true, null, 'A flake pressed between two fingers mashes easily but the poha is not mushy or wet.', '{"avoid": "Don''t soak it: wet poha turns into a lump.", "en": "A flake pressed between two fingers mashes easily but the poha is not mushy or wet.", "touch": "A flake pressed between two fingers mashes easily but isn''t mushy or wet."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 2, 'Heat the oil in a kadai and fry the peanuts until crunchy. Lift them out.', '{"en": "Heat the oil in a kadai and fry the peanuts until crunchy. Lift them out.", "hi": {"look": "मूँगफली एक रंग गहरी हो जाए।", "smell": "भुनी मूँगफली की ख़ुशबू, ठेले वाली जैसी।", "text": "कड़ाही में तेल गरम करें और मूँगफली कुरकुरी होने तक तलें। निकाल लें।"}, "hi-Latn": {"look": "Moongphali ek rang gehri ho jaaye.", "smell": "Bhuni moongphali ki khushboo, thele waali jaisi.", "text": "Kadaahi mein tel garam karein aur moongphali kurkuri hone tak talein. Nikaal lein."}}'::jsonb, (select id from public.techniques where slug = 'shallow_fry'), 180, false, null, 'The peanuts turn a shade darker and smell roasted.', '{"en": "The peanuts turn a shade darker and smell roasted.", "heat": "medium", "look": "The peanuts turn one shade darker.", "smell": "Roasted, like a street-side mungfali cart."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 3, 'In the same oil add mustard seeds. When they pop, add curry leaves and green chilli, then the onion. Cook until soft.', '{"en": "In the same oil add mustard seeds. When they pop, add curry leaves and green chilli, then the onion. Cook until soft.", "hi": {"look": "प्याज़ पारदर्शी हो, भूरा नहीं।", "smell": "करी पत्ता तेल में पड़ते ही तेज़ और ताज़ा महके।", "sound": "राई चटकती है; चटकने के बाद ही बाकी चीज़ें डालें।", "text": "उसी तेल में राई डालें। चटकने लगे तो करी पत्ता और हरी मिर्च डालें, फिर प्याज़। नरम होने तक पकाएँ।"}, "hi-Latn": {"look": "Pyaaz paardarshi ho, bhoora nahi.", "smell": "Curry patta tel mein padte hi tez aur taaza mehke.", "sound": "Rai chatakti hai; chatakne ke baad hi baaki cheezein daalein.", "text": "Usi tel mein rai daalein. Chatakne lage to curry patta aur hari mirch daalein, phir pyaaz. Naram hone tak pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 180, false, null, 'The onion turns translucent, not brown.', '{"en": "The onion turns translucent, not brown.", "heat": "medium", "look": "The onion turns translucent, not brown.", "smell": "Curry leaves smell fresh and sharp when they hit the oil.", "sound": "Mustard seeds pop; wait for the popping before adding the rest."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 4, 'Add the poha and toss gently on low heat. Cover and steam for 2 minutes.', '{"en": "Add the poha and toss gently on low heat. Cover and steam for 2 minutes.", "hi": {"look": "हर दाना पीला हो और ढक्कन उठाने पर भाप निकले।", "text": "पोहा डालें और धीमी आँच पर हल्के से मिलाएँ। ढककर 2 मिनट भाप में पकाएँ।", "touch": "पूरा अंदर तक गरम हो।"}, "hi-Latn": {"look": "Har daana peela ho aur dhakkan uthaane par bhaap nikle.", "text": "Poha daalein aur dheemi aanch par halke se milaayein. Dhak kar 2 minute bhaap mein pakaayein.", "touch": "Poora andar tak garam ho."}}'::jsonb, null, 120, true, null, 'The poha is hot all the way through and every flake is yellow.', '{"en": "The poha is hot all the way through and every flake is yellow.", "heat": "low", "look": "Every flake is yellow and steam rises when you lift the lid.", "touch": "Hot all the way through."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 5, 'Turn off the heat. Add the peanuts, lemon juice and coriander leaves and toss once.', '{"en": "Turn off the heat. Add the peanuts, lemon juice and coriander leaves and toss once.", "hi": {"taste": "नींबू और नमक चखकर देखें।", "text": "आँच बंद करें। मूँगफली, नींबू का रस और हरा धनिया डालकर एक बार मिलाएँ।"}, "hi-Latn": {"taste": "Nimbu aur namak chakh kar dekhein.", "text": "Aanch band karein. Moongphali, nimbu ka ras aur hara dhaniya daalkar ek baar milaayein."}}'::jsonb, null, 60, false, null, 'Taste for lemon and salt.', '{"en": "Taste for lemon and salt.", "taste": "Taste for lemon and salt."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'kanda-poha') and step_no > 5;

