insert into public.recipe_variation_rules (recipe_id, rule_type, condition, action, note) values
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 'omit', '{"allergen": "peanut"}'::jsonb, '{"omit": ["peanuts"]}'::jsonb, 'Leave out the peanuts; add a handful of roasted chana dal or none.'),
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 'add', '{"have": ["potato"]}'::jsonb, '{"add": [{"ingredient": "potato", "qty": 150, "unit": "g"}], "at_step": 3}'::jsonb, 'Add one small diced potato with the onion and cook covered until soft for batata poha.');

-- Recipe: kulcha (draft, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('kulcha', 'Tawa Kulcha', '{"en": "Tawa Kulcha", "hi": "तवा कुलचा", "hi-Latn": "Tawa Kulcha"}'::jsonb, 'Soft, thick kulchas on the tawa, no oven needed. A maida dough with curd and milk that rests an hour, topped with coriander or kalonji and finished with butter.', '{"hi": "तवे पर नरम, मोटे कुलचे, ओवन की ज़रूरत नहीं। दही और दूध वाला मैदे का आटा जो एक घंटा रखा जाता है, ऊपर धनिया या कलौंजी और आख़िर में मक्खन।", "hi-Latn": "Tawe par naram, mote kulche, oven ki zaroorat nahi. Dahi aur doodh waala maide ka aata jo ek ghanta rakha jaata hai, upar dhaniya ya kalonji aur aakhir mein makkhan."}'::jsonb, 'generic_north', 'component', 'veg', 2, 75, 15, 3, 1, array['tawa']::text[], array['basics']::text[], '{"acid": 0.1, "crunch": 0.2, "heat": 0, "rich": 0.6, "starch": 1, "sweet": 0.1}'::jsonb, array['grain']::text[], 'curated', 'draft', false)
