insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'kulcha'), 1, 'Mix maida, baking powder, soda, sugar and salt. Add curd and milk, then warm water a little at a time, and knead a soft, slightly sticky dough.', '{"en": "Mix maida, baking powder, soda, sugar and salt. Add curd and milk, then warm water a little at a time, and knead a soft, slightly sticky dough.", "hi": {"text": "मैदा, बेकिंग पाउडर, सोडा, चीनी और नमक मिलाएँ। दही और दूध डालें, फिर गुनगुना पानी थोड़ा-थोड़ा डालकर नरम, हल्का चिपचिपा आटा गूँधें।", "touch": "रोटी के आटे से नरम; उँगलियों पर थोड़ा चिपके।"}, "hi-Latn": {"text": "Maida, baking powder, soda, cheeni aur namak milaayein. Dahi aur doodh daalein, phir gunguna paani thoda-thoda daal kar naram, halka chipchipa aata goondhein.", "touch": "Roti ke aate se naram; ungliyon par thoda chipke."}}'::jsonb, (select id from public.techniques where slug = 'knead'), 480, false, null, 'Softer than roti dough; it sticks a little to your fingers.', '{"en": "Softer than roti dough; it sticks a little to your fingers.", "touch": "Softer than roti dough; it sticks a little to your fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kulcha'), 2, 'Coat with oil, cover and rest in a warm place.', '{"en": "Coat with oil, cover and rest in a warm place.", "hi": {"look": "आटा थोड़ा फूला हुआ और हल्का लगे।", "text": "तेल लगाएँ, ढकें और गरम जगह पर रखें।"}, "hi-Latn": {"look": "Aata thoda phoola hua aur halka lage.", "text": "Tel lagaayein, dhakein aur garam jagah par rakhein."}}'::jsonb, null, 3600, true, null, 'The dough looks a little puffed and feels airy.', '{"en": "The dough looks a little puffed and feels airy.", "look": "The dough looks a little puffed and feels airy."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kulcha'), 3, 'Roll a ball into a thick oval. Press kalonji and coriander on top, then brush the other side with water.', '{"en": "Roll a ball into a thick oval. Press kalonji and coriander on top, then brush the other side with water.", "hi": {"look": "लगभग दो रोटी जितना मोटा, ऊपर टॉपिंग दबी हुई।", "text": "लोई को मोटा लंबा गोल बेलें। ऊपर कलौंजी और धनिया दबाएँ, दूसरी तरफ़ पानी लगाएँ।"}, "hi-Latn": {"look": "Lagbhag do roti jitna mota, upar topping dabi hui.", "text": "Loi ko mota lamba gol belein. Upar kalonji aur dhaniya dabaayein, doosri taraf paani lagaayein."}}'::jsonb, null, 120, false, null, 'About as thick as two rotis, with the topping pressed in.', '{"en": "About as thick as two rotis, with the topping pressed in.", "look": "About as thick as two rotis, with the topping pressed in."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kulcha'), 4, 'Put it wet side down on a hot tawa. When bubbles rise, flip and cook the top until golden spots appear. Brush with butter and serve hot.', '{"en": "Put it wet side down on a hot tawa. When bubbles rise, flip and cook the top until golden spots appear. Brush with butter and serve hot.", "hi": {"look": "ऊपर फूले बुलबुले, फिर सुनहरे भूरे धब्बे।", "smell": "सिकी हुई मक्खन वाली ख़ुशबू।", "text": "गीली तरफ़ नीचे करके गरम तवे पर रखें। बुलबुले आएँ तो पलटें और ऊपर की तरफ़ सुनहरे धब्बे आने तक सेकें। मक्खन लगाकर गरम परोसें।"}, "hi-Latn": {"look": "Upar phoole bulbule, phir sunehre bhoore dhabbe.", "smell": "Siki hui makkhan waali khushboo.", "text": "Geeli taraf neeche karke garam tawe par rakhein. Bulbule aayein to paltein aur upar ki taraf sunehre dhabbe aane tak sekein. Makkhan laga kar garam parosein."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 180, false, null, 'Puffy bubbles on top, then golden brown patches. A toasty, buttery smell.', '{"en": "Puffy bubbles on top, then golden brown patches. A toasty, buttery smell.", "heat": "medium", "look": "Puffy bubbles on top, then golden brown patches.", "smell": "A toasty, buttery smell."}'::jsonb, null, null)
