insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 1, 'Cut the paneer into cubes and soak them in warm water so they stay soft. Grind the onion, ginger, garlic and green chilli to a paste, and the tomatoes to a separate puree.', '{"en": "Cut the paneer into cubes and soak them in warm water so they stay soft. Grind the onion, ginger, garlic and green chilli to a paste, and the tomatoes to a separate puree.", "hi": {"text": "पनीर के टुकड़े काटकर गुनगुने पानी में भिगो दें ताकि नरम रहें। प्याज़, अदरक, लहसुन और हरी मिर्च का पेस्ट बनाएँ, और टमाटर की अलग प्यूरी।", "touch": "गुनगुने पानी में पनीर नरम बना रहे।"}, "hi-Latn": {"text": "Paneer ke tukde kaatkar gungune paani mein bhigo dein taaki naram rahein. Pyaaz, adrak, lahsun aur hari mirch ka paste banaayein, aur tamatar ki alag puree.", "touch": "Gungune paani mein paneer naram bana rahe."}}'::jsonb, null, 600, false, null, 'The paneer stays soft in the warm water.', '{"en": "The paneer stays soft in the warm water.", "touch": "The paneer stays soft in the warm water."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 2, 'Heat the oil in a kadai. Add cumin and the bay leaf, then the onion paste. Cook, stirring.', '{"en": "Heat the oil in a kadai. Add cumin and the bay leaf, then the onion paste. Cook, stirring.", "hi": {"avoid": "बार-बार चलाएँ; प्याज़ का पेस्ट जल्दी तले में लगता है।", "look": "पेस्ट सुनहरा हो जाए।", "smell": "कच्चे प्याज़ की महक चली जाए।", "text": "कड़ाही में तेल गरम करें। जीरा और तेज पत्ता डालें, फिर प्याज़ का पेस्ट। चलाते हुए पकाएँ।"}, "hi-Latn": {"avoid": "Baar-baar chalaayein; pyaaz ka paste jaldi tale mein lagta hai.", "look": "Paste sunehra ho jaaye.", "smell": "Kachche pyaaz ki mehak chali jaaye.", "text": "Kadaahi mein tel garam karein. Jeera aur tej patta daalein, phir pyaaz ka paste. Chalaate hue pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 600, false, null, 'The raw onion smell goes and the paste turns golden.', '{"avoid": "Stir often; onion paste catches on the bottom quickly.", "en": "The raw onion smell goes and the paste turns golden.", "heat": "medium", "look": "The paste turns golden.", "smell": "The raw onion smell goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 3, 'Add turmeric, Kashmiri chilli and coriander powder with a splash of water, stir for a minute, then add the tomato puree. Keep cooking and stirring.', '{"en": "Add turmeric, Kashmiri chilli and coriander powder with a splash of water, stir for a minute, then add the tomato puree. Keep cooking and stirring.", "hi": {"look": "मसाला गाढ़ा और गहरा हो जाए और किनारों पर तेल अलग हो जाए।", "sound": "पानी सूखने पर मसाले के छींटे कम हो जाएँ।", "text": "हल्दी, कश्मीरी मिर्च और धनिया पाउडर थोड़े पानी के साथ डालें, एक मिनट चलाएँ, फिर टमाटर की प्यूरी डालें। चलाते हुए पकाते रहें।"}, "hi-Latn": {"look": "Masala gaadha aur gehra ho jaaye aur kinaaron par tel alag ho jaaye.", "sound": "Paani sookhne par masaale ke chheente kam ho jaayein.", "text": "Haldi, Kashmiri mirch aur dhaniya powder thode paani ke saath daalein, ek minute chalaayein, phir tamatar ki puree daalein. Chalaate hue pakaate rahein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 600, false, null, 'The masala thickens, darkens and the oil separates at the edges.', '{"en": "The masala thickens, darkens and the oil separates at the edges.", "heat": "medium", "look": "The masala thickens, darkens and the oil separates at the edges.", "sound": "The masala splutters less as the water cooks off."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 4, 'Add the peas, salt and 300 ml water. Cover and simmer until the peas are soft.', '{"en": "Add the peas, salt and 300 ml water. Cover and simmer until the peas are soft.", "hi": {"text": "मटर, नमक और 300 ml पानी डालें। ढककर मटर नरम होने तक पकाएँ।", "touch": "मटर दो उँगलियों में आसानी से दब जाए।"}, "hi-Latn": {"text": "Matar, namak aur 300 ml paani daalein. Dhak kar matar naram hone tak pakaayein.", "touch": "Matar do ungliyon mein aasaani se dab jaaye."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 480, true, null, 'Fresh peas take about 8 minutes; frozen peas about 4.', '{"en": "Fresh peas take about 8 minutes; frozen peas about 4.", "heat": "low", "touch": "A pea squashes easily between two fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 5, 'Drain the paneer and add it to the gravy. Simmer for 3 minutes only.', '{"en": "Drain the paneer and add it to the gravy. Simmer for 3 minutes only.", "hi": {"avoid": "पनीर को ज़्यादा देर न उबालें, वरना रबड़ जैसा हो जाएगा।", "text": "पनीर का पानी निकालकर ग्रेवी में डालें। सिर्फ़ 3 मिनट पकाएँ।", "touch": "चम्मच से दबाने पर पनीर नरम लगे।"}, "hi-Latn": {"avoid": "Paneer ko zyaada der na ubaalein, warna rubber jaisa ho jaayega.", "text": "Paneer ka paani nikaal kar gravy mein daalein. Sirf 3 minute pakaayein.", "touch": "Chammach se dabaane par paneer naram lage."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 180, true, null, 'Do not boil the paneer for long or it turns rubbery.', '{"avoid": "Don''t boil the paneer for long or it turns rubbery.", "en": "Do not boil the paneer for long or it turns rubbery.", "heat": "low", "touch": "The paneer is soft when pressed with a spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 6, 'Add garam masala, crushed kasuri methi and cream. Stir, top with coriander leaves and serve.', '{"en": "Add garam masala, crushed kasuri methi and cream. Stir, top with coriander leaves and serve.", "hi": {"smell": "कसूरी मेथी की हल्की मीठी, हरी ख़ुशबू।", "text": "गरम मसाला, मसली हुई कसूरी मेथी और क्रीम डालें। मिलाएँ, ऊपर हरा धनिया डालें और परोसें।"}, "hi-Latn": {"smell": "Kasoori methi ki halki meethi, hari khushboo.", "text": "Garam masala, masli hui kasoori methi aur cream daalein. Milaayein, upar hara dhaniya daalein aur parosein."}}'::jsonb, null, 60, false, null, 'Kasuri methi smells sweet and grassy.', '{"en": "Kasuri methi smells sweet and grassy.", "smell": "Kasuri methi smells sweet and grassy."}'::jsonb, null, null)
