  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 'diet', '{"diet": "vegan"}'::jsonb, '{"omit": ["fresh cream"], "replace": {"paneer": "tofu"}}'::jsonb, 'Firm tofu and no cream.'),
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 'diet', '{"diet": "jain"}'::jsonb, '{"add": [{"ingredient": "asafoetida", "qty": 0.2, "unit": "g"}], "omit": ["onion", "ginger", "garlic"]}'::jsonb, 'A tomato-only gravy with hing; add a little cashew paste for body.');

