  ('moong-dal-khichdi', 'Moong Dal Khichdi', '{"en": "Moong Dal Khichdi", "hi": "मूंग दाल खिचड़ी", "hi-Latn": "Moong Dal Khichdi"}'::jsonb, 'Soft rice and yellow moong dal cooked together with ghee, cumin and ginger. Light, one-pot and easy on the stomach.', '{"hi": "नरम चावल और पीली मूँग दाल, घी, जीरा और अदरक के साथ एक साथ पकी। हल्की, एक बर्तन वाली, पेट के लिए आसान।", "hi-Latn": "Naram chaawal aur peeli moong daal, ghee, jeera aur adrak ke saath ek saath paki. Halki, ek bartan wali, pet ke liye aasaan."}'::jsonb, 'generic_north', 'main', 'veg', 4, 15, 20, 1, 1, array['pressure_cooker']::text[], array['comforting', 'light', 'kids_friendly', 'one_pot']::text[], '{"acid": 0, "crunch": 0, "heat": 0.1, "rich": 0.4, "starch": 0.8, "sweet": 0}'::jsonb, array['dal', 'grain']::text[], 'curated', 'draft', false)
