insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'moong-dal-khichdi'), 1, 'Rinse the rice and dal together 2 to 3 times and soak them in fresh water.', '{"en": "Rinse the rice and dal together 2 to 3 times and soak them in fresh water.", "hi": {"look": "धोने का पानी लगभग साफ़ आए।", "text": "चावल और दाल एक साथ 2-3 बार धोएँ और ताज़े पानी में भिगो दें।"}, "hi-Latn": {"look": "Dhone ka paani lagbhag saaf aaye.", "text": "Chaawal aur daal ek saath 2-3 baar dhoyein aur taaze paani mein bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 900, true, null, 'The rinse water runs almost clear.', '{"en": "The rinse water runs almost clear.", "look": "The rinse water runs almost clear."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-dal-khichdi'), 2, 'Heat the ghee in the pressure cooker. Add cumin, hing and grated ginger and stir for 30 seconds.', '{"en": "Heat the ghee in the pressure cooker. Add cumin, hing and grated ginger and stir for 30 seconds.", "hi": {"avoid": "30 सेकंड काफ़ी है; अदरक भूरा न होने दें।", "smell": "भुने जीरे और ताज़े अदरक की ख़ुशबू।", "sound": "जीरा तुरंत चटकने लगे।", "text": "कुकर में घी गरम करें। जीरा, हींग और कसा अदरक डालकर 30 सेकंड चलाएँ।"}, "hi-Latn": {"avoid": "30 second kaafi hai; adrak bhoora na hone dein.", "smell": "Bhune jeere aur taaze adrak ki khushboo.", "sound": "Jeera turant chatakne lage.", "text": "Cooker mein ghee garam karein. Jeera, hing aur kasa adrak daalkar 30 second chalaayein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin sizzles and smells toasty.', '{"avoid": "Thirty seconds is enough; don''t let the ginger brown.", "en": "The cumin sizzles and smells toasty.", "heat": "medium", "smell": "Toasty cumin and fresh ginger.", "sound": "The cumin sizzles straight away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-dal-khichdi'), 3, 'Add the drained rice and dal, turmeric, salt and 900 ml water. Close the lid and cook on medium heat.', '{"en": "Add the drained rice and dal, turmeric, salt and 900 ml water. Close the lid and cook on medium heat.", "hi": {"branch": "नरम खिचड़ी के लिए आधा कप पानी और डालें", "sound": "सीटियाँ गिनें, फिर खोलने से पहले प्रेशर अपने आप उतरने दें।", "text": "पानी निकाले हुए चावल-दाल, हल्दी, नमक और 900 ml पानी डालें। ढक्कन बंद करके मध्यम आँच पर पकाएँ।"}, "hi-Latn": {"branch": "Naram khichdi ke liye aadha cup paani aur daalein", "sound": "Seetiyaan ginein, phir kholne se pehle pressure apne aap utarne dein.", "text": "Paani nikaale hue chaawal-daal, haldi, namak aur 900 ml paani daalein. Dhakkan band karke madhyam aanch par pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 900, false, 4, 'Let the pressure drop by itself before opening.', '{"en": "Let the pressure drop by itself before opening.", "heat": "medium", "sound": "Count the whistles, then let the pressure drop by itself before opening."}'::jsonb, '{"action": "Add another half cup of water for a softer khichdi", "age_group": "elder"}'::jsonb, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-dal-khichdi'), 4, 'Stir and mash lightly. Add hot water if it is too thick, and serve with a little ghee on top.', '{"en": "Stir and mash lightly. Add hot water if it is too thick, and serve with a little ghee on top.", "hi": {"look": "चम्मच से धीरे-धीरे बहे, गाढ़े दलिये जैसी।", "text": "चलाएँ और हल्का मसलें। बहुत गाढ़ी हो तो गरम पानी डालें, और ऊपर थोड़ा घी डालकर परोसें।", "touch": "चावल और दाल आसानी से एक साथ मसल जाएँ।"}, "hi-Latn": {"look": "Chammach se dheere-dheere bahe, gaadhe daliye jaisi.", "text": "Chalaayein aur halka maslein. Bahut gaadhi ho to garam paani daalein, aur upar thoda ghee daalkar parosein.", "touch": "Chaawal aur daal aasaani se ek saath masal jaayein."}}'::jsonb, null, 120, false, null, 'It should flow slowly from the spoon, like a thick porridge. It thickens as it stands.', '{"en": "It should flow slowly from the spoon, like a thick porridge. It thickens as it stands.", "look": "It flows slowly from the spoon, like a thick porridge.", "touch": "The rice and dal mash easily together."}'::jsonb, null, null)
