insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('onion-tomato-masala', 'Onion-Tomato Masala', '{"en": "Onion-Tomato Masala", "hi": "प्याज़-टमाटर मसाला", "hi-Latn": "Pyaz-Tamatar Masala"}'::jsonb, 'A Sunday batch of the base most North Indian gravies start with. Keep it in the fridge for up to five days (or freeze in portions for a month) and weekday dals, sabzis and curries skip the slowest part.', '{"hi": "रविवार को बना लें, ज़्यादातर उत्तर भारतीय ग्रेवी इसी से शुरू होती हैं। फ़्रिज में पाँच दिन तक रखें (या हिस्सों में एक महीने के लिए जमा दें), और हफ़्ते में दाल, सब्ज़ी और करी का सबसे धीमा काम बच जाता है।", "hi-Latn": "Ravivaar ko bana lein, zyadatar North Indian gravy isi se shuru hoti hain. Fridge mein paanch din tak rakhein (ya hisson mein ek mahine ke liye jama dein), aur hafte mein dal, sabzi aur curry ka sabse dheema kaam bach jaata hai."}'::jsonb, 'generic_north', 'component', 'vegan', 8, 15, 35, 2, 2, array['kadai', 'mixer_grinder']::text[], array['basics']::text[], '{"acid": 0.5, "crunch": 0, "heat": 0.4, "rich": 0.5, "starch": 0.1, "sweet": 0.2}'::jsonb, array['sabzi']::text[], 'curated', 'draft', false)
