insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'onion-tomato-masala'), 1, 'Grind the onions coarsely, and the tomatoes, ginger and garlic smooth, separately.', '{"en": "Grind the onions coarsely, and the tomatoes, ginger and garlic smooth, separately.", "hi": {"look": "प्याज़ कद्दूकस जैसा दरदरा, टमाटर एकदम चिकनी प्यूरी।", "text": "प्याज़ को दरदरा, और टमाटर, अदरक और लहसुन को अलग से बारीक पीस लें।"}, "hi-Latn": {"look": "Pyaz kaddukas jaisa dardara, tamatar ekdam chikni puree.", "text": "Pyaz ko dardara, aur tamatar, adrak aur lehsun ko alag se baareek pees lein."}}'::jsonb, null, 600, false, null, 'Onions coarse like grated, tomatoes a smooth puree.', '{"en": "Onions coarse like grated, tomatoes a smooth puree.", "look": "Onions coarse like grated, tomatoes a smooth puree."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'onion-tomato-masala'), 2, 'Heat the oil in a wide kadai and fry the onion paste, stirring often, until deep golden.', '{"en": "Heat the oil in a wide kadai and fry the onion paste, stirring often, until deep golden.", "hi": {"avoid": "रंग गहरा हो तो और ज़्यादा चलाएँ; जले टुकड़े पूरे मसाले को कड़वा कर देते हैं।", "look": "गहरा सुनहरा भूरा, और किनारों पर तेल दिखे।", "smell": "मीठी, भुनी प्याज़ की ख़ुशबू।", "text": "चौड़ी कड़ाही में तेल गरम करें और प्याज़ का पेस्ट बार-बार चलाते हुए गहरा सुनहरा होने तक भूनें।"}, "hi-Latn": {"avoid": "Rang gehra ho to aur zyada chalaayein; jale tukde poore masale ko kadva kar dete hain.", "look": "Gehra sunehra bhoora, aur kinaaron par tel dikhe.", "smell": "Meethi, bhuni pyaz ki khushboo.", "text": "Chaudi kadaahi mein tel garam karein aur pyaz ka paste baar-baar chalaate hue gehra sunehra hone tak bhoonein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 900, false, null, 'Deep golden brown, and the oil shows at the edges. Sweet, toasty onion. Stir more as it darkens; burnt bits make the whole batch bitter.', '{"avoid": "Stir more as it darkens; burnt bits make the whole batch bitter.", "en": "Deep golden brown, and the oil shows at the edges. Sweet, toasty onion. Stir more as it darkens; burnt bits make the whole batch bitter.", "heat": "medium", "look": "Deep golden brown, and the oil shows at the edges.", "smell": "Sweet, toasty onion."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'onion-tomato-masala'), 3, 'Add the tomato puree, the powders and salt. Cook, stirring, until thick and the oil separates.', '{"en": "Add the tomato puree, the powders and salt. Cook, stirring, until thick and the oil separates.", "hi": {"avoid": "यह उछलता है: ढक्कन आधा रखें और थोड़ा दूर रहें।", "look": "गाढ़ा, गहरा लाल, और ऊपर तेल तैरे।", "safety": "गरम मसाला उछलता है; ढक्कन आधा रखें और बच्चों को दूर रखें।", "text": "टमाटर प्यूरी, मसाले और नमक डालें। चलाते हुए पकाएँ जब तक गाढ़ा न हो जाए और तेल अलग न हो।"}, "hi-Latn": {"avoid": "Yeh uchhalta hai: dhakkan aadha rakhein aur thoda door rahein.", "look": "Gaadha, gehra laal, aur upar tel taire.", "safety": "Garam masala uchhalta hai; dhakkan aadha rakhein aur bachchon ko door rakhein.", "text": "Tamatar puree, masale aur namak daalein. Chalaate hue pakaayein jab tak gaadha na ho jaaye aur tel alag na ho."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 900, false, null, 'Thick, dark red, and oil pools on the surface. It splutters: keep a lid half on and stand back.', '{"avoid": "It splutters: keep a lid half on and stand back.", "en": "Thick, dark red, and oil pools on the surface. It splutters: keep a lid half on and stand back.", "heat": "medium", "look": "Thick, dark red, and oil pools on the surface."}'::jsonb, null, 'Hot masala splutters; keep a lid half on and keep children away.'),
  ((select id from public.recipes where household_id is null and slug = 'onion-tomato-masala'), 4, 'Cool completely, then store in a clean, dry, closed jar in the fridge. Use a clean dry spoon each time.', '{"en": "Cool completely, then store in a clean, dry, closed jar in the fridge. Use a clean dry spoon each time.", "hi": {"safety": "फ़्रिज में 5 दिन, फ़्रीज़र में एक महीना चलता है। साफ़ सूखा चम्मच लें ताकि ख़राब न हो।", "text": "पूरी तरह ठंडा करें, फिर साफ़, सूखे, बंद डिब्बे में फ़्रिज में रखें। हर बार साफ़ सूखा चम्मच लें।", "touch": "डिब्बे में डालने से पहले छूने पर ठंडा हो।"}, "hi-Latn": {"safety": "Fridge mein 5 din, freezer mein ek mahina chalta hai. Saaf sookha chammach lein taaki kharaab na ho.", "text": "Poori tarah thanda karein, phir saaf, sookhe, band dibbe mein fridge mein rakhein. Har baar saaf sookha chammach lein.", "touch": "Dibbe mein daalne se pehle chhoone par thanda ho."}}'::jsonb, null, 1200, false, null, 'Cool to the touch before it goes in the jar.', '{"en": "Cool to the touch before it goes in the jar.", "touch": "Cool to the touch before it goes in the jar."}'::jsonb, null, 'Keeps 5 days in the fridge or a month frozen. Use a clean dry spoon so it doesn''t spoil.')
