insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('paratha', 'Plain Paratha', '{"en": "Plain Paratha", "hi": "सादा पराठा", "hi-Latn": "Saada Paratha"}'::jsonb, 'Flaky layered parathas from the same atta dough as roti, folded with ghee and cooked crisp on the tawa. One katori of atta makes about three parathas.', '{"hi": "रोटी वाले आटे से बने परतदार पराठे, घी लगाकर मोड़े और तवे पर कुरकुरे सेके। एक कटोरी आटे से लगभग तीन पराठे।", "hi-Latn": "Roti waale aate se bane paratdaar parathe, ghee lagaakar mode aur tawe par kurkure seke. Ek katori aate se lagbhag teen parathe."}'::jsonb, 'generic_north', 'component', 'veg', 2, 30, 20, 2, 1, array['tawa']::text[], array['basics', 'tiffin']::text[], '{"acid": 0, "crunch": 0.4, "heat": 0, "rich": 0.5, "starch": 1, "sweet": 0}'::jsonb, array['grain']::text[], 'curated', 'draft', false)
