  ((select id from public.recipes where household_id is null and slug = 'paratha'), (select id from public.ingredients where canonical_name = 'whole wheat flour'), 'whole wheat flour', 150, 'g', '2 katori atta (6 parathas)', false, null, 'starch', '[]'::jsonb, 0),
  ((select id from public.recipes where household_id is null and slug = 'paratha'), (select id from public.ingredients where canonical_name = 'salt'), 'salt', 1.5, 'g', '1 chutki', false, null, 'spice', '[]'::jsonb, 1),
