insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'paratha'), 1, 'Mix the atta, salt and one spoon of ghee. Add about half a katori of water a little at a time and knead a soft dough, then cover and rest.', '{"en": "Mix the atta, salt and one spoon of ghee. Add about half a katori of water a little at a time and knead a soft dough, then cover and rest.", "hi": {"text": "आटा, नमक और एक चम्मच घी मिलाएँ। लगभग आधी कटोरी पानी थोड़ा-थोड़ा डालकर नरम आटा गूँधें, फिर ढककर आराम दें।", "touch": "नरम, चिकना और चिपचिपा नहीं; उँगली का गड्ढा धीरे से वापस भरे।"}, "hi-Latn": {"text": "Aata, namak aur ek chammach ghee milaayein. Lagbhag aadhi katori paani thoda-thoda daal kar naram aata goondhein, phir dhak kar aaraam dein.", "touch": "Naram, chikna aur chipchipa nahi; ungli ka gaddha dheere se waapas bhare."}}'::jsonb, (select id from public.techniques where slug = 'knead'), 1200, true, null, 'Soft, smooth and not sticky; a finger dent springs back slowly.', '{"en": "Soft, smooth and not sticky; a finger dent springs back slowly.", "touch": "Soft, smooth and not sticky; a finger dent springs back slowly."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'paratha'), 2, 'Roll a ball into a small circle, spread a little ghee, fold in half and in half again into a triangle, and roll it out again.', '{"en": "Roll a ball into a small circle, spread a little ghee, fold in half and in half again into a triangle, and roll it out again.", "hi": {"avoid": "हल्के हाथ से बेलें ताकि परतें आपस में न चिपकें।", "look": "किनारों पर घी की परतें दिखें।", "text": "लोई को छोटा गोल बेलें, थोड़ा घी लगाएँ, आधा मोड़ें और फिर आधा मोड़कर तिकोना बनाएँ, और दोबारा बेलें।"}, "hi-Latn": {"avoid": "Halke haath se belein taaki partein aapas mein na chipkein.", "look": "Kinaaron par ghee ki partein dikhein.", "text": "Loi ko chhota gol belein, thoda ghee lagaayein, aadha modein aur phir aadha mod kar tikona banaayein, aur dobaara belein."}}'::jsonb, null, 120, false, null, 'You can see the ghee layers at the edges. Roll gently so the layers don''t stick together.', '{"avoid": "Roll gently so the layers don''t stick together.", "en": "You can see the ghee layers at the edges. Roll gently so the layers don''t stick together.", "look": "You can see the ghee layers at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'paratha'), 3, 'Cook on a hot tawa, flipping once the base has spots. Spread ghee on both sides and press the edges with a spatula until crisp and golden.', '{"en": "Cook on a hot tawa, flipping once the base has spots. Spread ghee on both sides and press the edges with a spatula until crisp and golden.", "hi": {"look": "दोनों तरफ़ सुनहरे भूरे धब्बे और फूली हुई परतें।", "sound": "दबाते समय घी छनछनाए।", "text": "गरम तवे पर सेकें, नीचे धब्बे आएँ तो पलटें। दोनों तरफ़ घी लगाएँ और कलछी से किनारे दबाते हुए सुनहरा और कुरकुरा करें।"}, "hi-Latn": {"look": "Dono taraf sunehre bhoore dhabbe aur phooli hui partein.", "sound": "Dabaate samay ghee chhanchhanaaye.", "text": "Garam tawe par sekein, neeche dhabbe aayein to paltein. Dono taraf ghee lagaayein aur kalchhi se kinaare dabaate hue sunehra aur kurkura karein."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 180, false, null, 'Golden brown patches on both sides and puffed layers. The ghee sizzles as you press.', '{"en": "Golden brown patches on both sides and puffed layers. The ghee sizzles as you press.", "heat": "medium", "look": "Golden brown patches on both sides and puffed layers.", "sound": "The ghee sizzles as you press."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'paratha'), 4, 'Serve hot with curd, pickle or any sabzi. Leftover dough keeps two days in a closed box in the fridge.', '{"en": "Serve hot with curd, pickle or any sabzi. Leftover dough keeps two days in a closed box in the fridge.", "hi": {"text": "दही, अचार या किसी भी सब्ज़ी के साथ गरम परोसें। बचा आटा बंद डिब्बे में फ़्रिज में दो दिन चलता है।", "touch": "तोड़ने पर बाहर से कुरकुरा और अंदर से नरम।"}, "hi-Latn": {"text": "Dahi, achaar ya kisi bhi sabzi ke saath garam parosein. Bacha aata band dibbe mein fridge mein do din chalta hai.", "touch": "Todne par baahar se kurkura aur andar se naram."}}'::jsonb, null, null, false, null, 'Crisp outside and soft inside when torn.', '{"en": "Crisp outside and soft inside when torn.", "touch": "Crisp outside and soft inside when torn."}'::jsonb, null, null)
