-- Recipe: plain-dal (draft, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('plain-dal', 'Plain Dal', '{"en": "Plain Dal", "hi": "सादी दाल", "hi-Latn": "Saadi Dal"}'::jsonb, 'Everyday arhar dal with haldi and salt and a small jeera tadka. The first dal anyone should learn: one katori feeds two, with rice or roti.', '{"hi": "रोज़ की अरहर दाल, हल्दी-नमक और छोटे से जीरे के तड़के के साथ। सबसे पहले सीखने वाली दाल: एक कटोरी दो लोगों के लिए, चावल या रोटी के साथ।", "hi-Latn": "Roz ki arhar dal, haldi-namak aur chhote se jeere ke tadke ke saath. Sabse pehle seekhne waali dal: ek katori do logon ke liye, chaawal ya roti ke saath."}'::jsonb, 'generic_north', 'component', 'veg', 2, 5, 20, 1, 1, array['pressure_cooker']::text[], array['basics', 'comforting', 'kids_friendly', 'one_pot']::text[], '{"acid": 0, "crunch": 0, "heat": 0.1, "rich": 0.4, "starch": 0.4, "sweet": 0}'::jsonb, array['dal']::text[], 'curated', 'draft', false)
