insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'plain-dal'), 1, 'Rinse the dal two or three times. Put it in the cooker with turmeric, salt and three katori of water.', '{"en": "Rinse the dal two or three times. Put it in the cooker with turmeric, salt and three katori of water.", "hi": {"look": "धोने का पानी लगभग साफ़ हो जाए।", "text": "दाल को दो-तीन बार धोएँ। कुकर में हल्दी, नमक और तीन कटोरी पानी के साथ डालें।"}, "hi-Latn": {"look": "Dhone ka paani lagbhag saaf ho jaaye.", "text": "Dal ko do-teen baar dhoyein. Cooker mein haldi, namak aur teen katori paani ke saath daalein."}}'::jsonb, null, 120, false, null, 'The rinse water runs almost clear.', '{"en": "The rinse water runs almost clear.", "look": "The rinse water runs almost clear."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'plain-dal'), 2, 'Close the cooker and cook for three whistles, then let the pressure drop by itself.', '{"en": "Close the cooker and cook for three whistles, then let the pressure drop by itself.", "hi": {"look": "खोलने पर दाल नरम हो और चम्मच से आसानी से घुटे।", "safety": "कुकर तभी खोलें जब प्रेशर पूरी तरह उतर जाए।", "sound": "तीन सीटी गिनें।", "text": "कुकर बंद करके तीन सीटी लगाएँ, फिर प्रेशर अपने आप उतरने दें।"}, "hi-Latn": {"look": "Kholne par dal naram ho aur chammach se aasaani se ghute.", "safety": "Cooker tabhi kholein jab pressure poori tarah utar jaaye.", "sound": "Teen seeti ginein.", "text": "Cooker band karke teen seeti lagaayein, phir pressure apne aap utarne dein."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 720, false, 3, 'When opened, the dal is soft and mashes easily with a spoon. Count three whistles.', '{"en": "When opened, the dal is soft and mashes easily with a spoon. Count three whistles.", "heat": "medium", "look": "When opened, the dal is soft and mashes easily with a spoon.", "sound": "Count three whistles."}'::jsonb, null, 'Open the cooker only when the pressure has fully dropped.'),
  ((select id from public.recipes where household_id is null and slug = 'plain-dal'), 3, 'Whisk the dal smooth and add hot water if it''s too thick. Simmer for two minutes.', '{"en": "Whisk the dal smooth and add hot water if it''s too thick. Simmer for two minutes.", "hi": {"look": "गाढ़े सूप की तरह बहे।", "text": "दाल को घोंटकर एकसार करें और ज़्यादा गाढ़ी हो तो गरम पानी डालें। दो मिनट उबालें।"}, "hi-Latn": {"look": "Gaadhe soup ki tarah bahe.", "text": "Dal ko ghont kar eksaar karein aur zyada gaadhi ho to garam paani daalein. Do minute ubaalein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 120, false, null, 'It pours like thick soup.', '{"en": "It pours like thick soup.", "heat": "low", "look": "It pours like thick soup."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'plain-dal'), 4, 'Heat ghee in a small pan, add cumin and hing, and pour it over the dal.', '{"en": "Heat ghee in a small pan, add cumin and hing, and pour it over the dal.", "hi": {"avoid": "अगर जीरा काला हो जाए तो तड़का दोबारा करें।", "sound": "जीरा चटके और तड़का डालते ही दाल छनछनाए।", "text": "छोटी कड़ाही में घी गरम करें, जीरा और हींग डालें और दाल पर डाल दें।"}, "hi-Latn": {"avoid": "Agar jeera kaala ho jaaye to tadka dobaara karein.", "sound": "Jeera chatke aur tadka daalte hi dal chhanchhanaaye.", "text": "Chhoti kadaahi mein ghee garam karein, jeera aur hing daalein aur dal par daal dein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 30, false, null, 'The cumin crackles and the dal sizzles as the tadka goes in. If the cumin turns black, start the tadka again.', '{"avoid": "If the cumin turns black, start the tadka again.", "en": "The cumin crackles and the dal sizzles as the tadka goes in. If the cumin turns black, start the tadka again.", "heat": "medium", "sound": "The cumin crackles and the dal sizzles as the tadka goes in."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
