  ((select id from public.recipes where household_id is null and slug = 'puri'), (select id from public.ingredients where canonical_name = 'whole wheat flour'), 'whole wheat flour', 150, 'g', '2 katori atta (10 puris)', false, null, 'starch', '[]'::jsonb, 0),
  ((select id from public.recipes where household_id is null and slug = 'puri'), (select id from public.ingredients where canonical_name = 'semolina'), 'semolina', 10, 'g', '1 chammach suji', true, null, 'starch', '[]'::jsonb, 1),
  ((select id from public.recipes where household_id is null and slug = 'puri'), (select id from public.ingredients where canonical_name = 'salt'), 'salt', 1.5, 'g', '1 chutki', false, null, 'spice', '[]'::jsonb, 2),
  ((select id from public.recipes where household_id is null and slug = 'puri'), (select id from public.ingredients where canonical_name = 'refined oil'), 'refined oil', 250, 'ml', 'frying oil (most is left over)', false, null, 'fat', '[]'::jsonb, 3);

insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'puri'), 1, 'Mix atta, suji, salt and one spoon of oil. Add water a little at a time, about a third of a katori, and knead a stiff dough. Rest it covered.', '{"en": "Mix atta, suji, salt and one spoon of oil. Add water a little at a time, about a third of a katori, and knead a stiff dough. Rest it covered.", "hi": {"avoid": "नरम आटा तेल पीता है; नरम लगे तो एक चम्मच आटा मिलाएँ।", "text": "आटा, सूजी, नमक और एक चम्मच तेल मिलाएँ। लगभग एक तिहाई कटोरी पानी थोड़ा-थोड़ा डालकर सख़्त आटा गूँधें। ढककर रखें।", "touch": "रोटी के आटे से सख़्त: उँगली का गड्ढा वैसा ही रहे।"}, "hi-Latn": {"avoid": "Naram aata tel peeta hai; naram lage to ek chammach aata milaayein.", "text": "Aata, suji, namak aur ek chammach tel milaayein. Lagbhag ek tihaai katori paani thoda-thoda daal kar sakht aata goondhein. Dhak kar rakhein.", "touch": "Roti ke aate se sakht: ungli ka gaddha waisa hi rahe."}}'::jsonb, (select id from public.techniques where slug = 'knead'), 900, true, null, 'Firmer than roti dough: a finger dent stays put. Soft dough drinks oil; add a spoon of atta if it feels soft.', '{"avoid": "Soft dough drinks oil; add a spoon of atta if it feels soft.", "en": "Firmer than roti dough: a finger dent stays put. Soft dough drinks oil; add a spoon of atta if it feels soft.", "touch": "Firmer than roti dough: a finger dent stays put."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'puri'), 2, 'Heat the oil in a kadai. Roll small balls into thick palm-sized circles, using a drop of oil instead of dry atta.', '{"en": "Heat the oil in a kadai. Roll small balls into thick palm-sized circles, using a drop of oil instead of dry atta.", "hi": {"avoid": "सूखा आटा तेल में जलकर उसे काला करता है।", "look": "आटे का छोटा टुकड़ा डालते ही ऊपर आ जाए: तेल तैयार है।", "safety": "बच्चों को कड़ाही से दूर रखें और गरम तेल को कभी अकेला न छोड़ें।", "text": "कड़ाही में तेल गरम करें। छोटी लोइयों को हथेली जितना मोटा गोल बेलें, सूखे आटे की जगह एक बूँद तेल लगाकर।"}, "hi-Latn": {"avoid": "Sookha aata tel mein jal kar use kaala karta hai.", "look": "Aate ka chhota tukda daalte hi upar aa jaaye: tel taiyaar hai.", "safety": "Bachchon ko kadaahi se door rakhein aur garam tel ko kabhi akela na chhodein.", "text": "Kadaahi mein tel garam karein. Chhoti loiyon ko hatheli jitna mota gol belein, sookhe aate ki jagah ek boond tel lagaakar."}}'::jsonb, (select id from public.techniques where slug = 'deep_fry'), 300, false, null, 'A pinch of dough rises to the top straight away: the oil is ready. Dry atta burns in the oil and darkens it.', '{"avoid": "Dry atta burns in the oil and darkens it.", "en": "A pinch of dough rises to the top straight away: the oil is ready. Dry atta burns in the oil and darkens it.", "heat": "medium", "look": "A pinch of dough rises to the top straight away: the oil is ready."}'::jsonb, null, 'Keep children away from the kadai and never leave hot oil alone.'),
  ((select id from public.recipes where household_id is null and slug = 'puri'), 3, 'Slide in one puri, press it gently with the back of a slotted spoon until it puffs, flip and fry until light golden. Drain on paper.', '{"en": "Slide in one puri, press it gently with the back of a slotted spoon until it puffs, flip and fry until light golden. Drain on paper.", "hi": {"look": "कुछ ही सेकंड में गुब्बारे जैसी फूले और हल्की सुनहरी हो जाए।", "safety": "पूरी तेल के पास से धीरे डालें ताकि छींटे न उड़ें।", "sound": "तेज़ लेकिन हल्की छनछनाहट, ज़ोर का शोर नहीं।", "text": "एक पूरी धीरे से डालें, झारे के पिछले हिस्से से हल्का दबाएँ जब तक फूल न जाए, पलटें और हल्की सुनहरी होने तक तलें। काग़ज़ पर निकालें।"}, "hi-Latn": {"look": "Kuch hi second mein gubbaare jaisi phoole aur halki sunehri ho jaaye.", "safety": "Puri tel ke paas se dheere daalein taaki chheente na udein.", "sound": "Tez lekin halki chhanchhanaahat, zor ka shor nahi.", "text": "Ek puri dheere se daalein, jhaare ke pichhle hisse se halka dabaayein jab tak phool na jaaye, paltein aur halki sunehri hone tak talein. Kaagaz par nikaalein."}}'::jsonb, (select id from public.techniques where slug = 'deep_fry'), 40, false, null, 'It balloons up within seconds and turns light golden. A lively sizzle, not a roar.', '{"en": "It balloons up within seconds and turns light golden. A lively sizzle, not a roar.", "heat": "medium", "look": "It balloons up within seconds and turns light golden.", "sound": "A lively sizzle, not a roar."}'::jsonb, null, 'Slide puris in close to the oil so it doesn''t splash.')
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
