  ('rajma', 'Rajma', '{"en": "Rajma", "hi": "राजमा", "hi-Latn": "Rajma"}'::jsonb, 'Kidney beans soaked overnight, pressure-cooked until creamy and simmered in a thick onion-tomato masala. Best with steamed rice.', '{"hi": "रात भर भीगा राजमा, कुकर में मलाईदार पका, गाढ़े प्याज़-टमाटर मसाले में। चावल के साथ सबसे अच्छा।", "hi-Latn": "Raat bhar bheega rajma, cooker mein malaidaar paka, gaadhe pyaaz-tamatar masaale mein. Chaawal ke saath sabse achha."}'::jsonb, 'punjabi', 'main', 'vegan', 4, 20, 60, 2, 2, array['pressure_cooker', 'kadai']::text[], array['comforting', 'high_protein']::text[], '{"acid": 0.4, "crunch": 0, "heat": 0.3, "rich": 0.6, "starch": 0.6, "sweet": 0}'::jsonb, array['dal']::text[], 'curated', 'draft', false)
