insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 1, 'Rinse the rajma and soak in plenty of water overnight, at least 8 hours.', '{"en": "Rinse the rajma and soak in plenty of water overnight, at least 8 hours.", "hi": {"look": "दाने दोगुने हो जाएँ और छिलका चिकना हो।", "text": "राजमा धोकर ढेर सारे पानी में रात भर, कम से कम 8 घंटे भिगोएँ।"}, "hi-Latn": {"look": "Daane doguna ho jaayein aur chhilka chikna ho.", "text": "Rajma dhokar dher saare paani mein raat bhar, kam se kam 8 ghante bhigoyein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 28800, false, null, 'The beans double in size and the skins are smooth.', '{"en": "The beans double in size and the skins are smooth.", "look": "The beans double in size and the skins are smooth."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 2, 'Drain and throw away the soaking water. Pressure-cook the rajma with 750 ml fresh water and the salt.', '{"en": "Drain and throw away the soaking water. Pressure-cook the rajma with 750 ml fresh water and the salt.", "hi": {"safety": "कच्चा या अधपका राजमा ज़हरीला होता है। हमेशा भिगोएँ, भिगोने का पानी फेंकें, और हर दाना पूरी तरह नरम होने तक पकाएँ। कोई दाना सख़्त लगे तो और सीटियाँ लगाएँ। राजमा को कभी कच्चा स्लो कुकर में न पकाएँ।", "sound": "सीटियाँ गिनें, फिर प्रेशर अपने आप उतरने दें।", "text": "भिगोने का पानी फेंक दें। राजमा को 750 ml ताज़े पानी और नमक के साथ कुकर में पकाएँ।", "touch": "एक दाना दो उँगलियों में आसानी से मसल जाए और अंदर से मलाईदार हो।"}, "hi-Latn": {"safety": "Kachcha ya adhpaka rajma zehreela hota hai. Hamesha bhigoyein, bhigone ka paani phenkein, aur har daana poori tarah naram hone tak pakaayein. Koi daana sakht lage to aur seetiyaan lagaayein. Rajma ko kabhi kachcha slow cooker mein na pakaayein.", "sound": "Seetiyaan ginein, phir pressure apne aap utarne dein.", "text": "Bhigone ka paani phenk dein. Rajma ko 750 ml taaze paani aur namak ke saath cooker mein pakaayein.", "touch": "Ek daana do ungliyon mein aasaani se masal jaaye aur andar se malaidaar ho."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 1800, false, 8, 'Let the pressure drop by itself. A bean should mash easily between two fingers and be creamy inside.', '{"en": "Let the pressure drop by itself. A bean should mash easily between two fingers and be creamy inside.", "heat": "medium", "sound": "Count the whistles, then let the pressure drop by itself.", "touch": "A bean mashes easily between two fingers and is creamy inside."}'::jsonb, null, 'Raw or undercooked kidney beans are poisonous. Always soak, throw away the soaking water, and cook until every bean is completely soft. If any bean is still firm, cook for more whistles. Never cook rajma from raw in a slow cooker.'),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 3, 'Heat the oil in a kadai. Add cumin and the bay leaf, then the finely chopped onion and cook until deep golden.', '{"en": "Heat the oil in a kadai. Add cumin and the bay leaf, then the finely chopped onion and cook until deep golden.", "hi": {"avoid": "तेज़ आँच पर जल्दी न करें: बीच पकने से पहले किनारे जल जाते हैं।", "look": "प्याज़ एक जैसा सुनहरा-भूरा हो।", "smell": "भुने प्याज़ की मीठी ख़ुशबू।", "text": "कड़ाही में तेल गरम करें। जीरा और तेज पत्ता डालें, फिर बारीक कटा प्याज़ गहरा सुनहरा होने तक पकाएँ।"}, "hi-Latn": {"avoid": "Tez aanch par jaldi na karein: beech pakne se pehle kinaare jal jaate hain.", "look": "Pyaaz ek jaisa sunehra-bhoora ho.", "smell": "Bhune pyaaz ki meethi khushboo.", "text": "Kadaahi mein tel garam karein. Jeera aur tej patta daalein, phir bareek kata pyaaz gehra sunehra hone tak pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 600, false, null, 'The onion is evenly golden brown at the edges.', '{"avoid": "Don''t rush on high heat: the edges burn before the middle cooks.", "en": "The onion is evenly golden brown at the edges.", "heat": "medium", "look": "The onion is evenly golden brown.", "smell": "Sweet, browned onion."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 4, 'Add grated ginger, garlic and green chilli for a minute, then the tomato puree, turmeric, Kashmiri chilli and coriander powder. Cook, stirring.', '{"en": "Add grated ginger, garlic and green chilli for a minute, then the tomato puree, turmeric, Kashmiri chilli and coriander powder. Cook, stirring.", "hi": {"look": "मसाला गाढ़ा और गहरा हो और किनारे से तेल छोड़ दे।", "smell": "कच्चे टमाटर की महक चली जाए।", "text": "कसा अदरक, लहसुन और हरी मिर्च एक मिनट भूनें, फिर टमाटर की प्यूरी, हल्दी, कश्मीरी मिर्च और धनिया पाउडर डालें। चलाते हुए पकाएँ।"}, "hi-Latn": {"look": "Masala gaadha aur gehra ho aur kinaare se tel chhod de.", "smell": "Kachche tamatar ki mehak chali jaaye.", "text": "Kasa adrak, lahsun aur hari mirch ek minute bhoonein, phir tamatar ki puree, haldi, Kashmiri mirch aur dhaniya powder daalein. Chalaate hue pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 600, false, null, 'The masala is thick and dark and the oil leaves the sides.', '{"en": "The masala is thick and dark and the oil leaves the sides.", "heat": "medium", "look": "The masala is thick and dark and the oil leaves the sides.", "smell": "The raw tomato smell is gone."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 5, 'Add the rajma with its cooking water. Mash a few beans against the side of the pan for body and simmer on low heat.', '{"en": "Add the rajma with its cooking water. Mash a few beans against the side of the pan for body and simmer on low heat.", "hi": {"avoid": "हर कुछ मिनट में तले से चलाएँ; राजमा की ग्रेवी चिपकती है।", "look": "ग्रेवी गाढ़ी हो और दानों पर लिपट जाए।", "text": "राजमा उसके पानी के साथ डालें। गाढ़ेपन के लिए कुछ दाने कड़ाही की दीवार पर मसल दें और धीमी आँच पर पकाएँ।"}, "hi-Latn": {"avoid": "Har kuch minute mein tale se chalaayein; rajma ki gravy chipakti hai.", "look": "Gravy gaadhi ho aur daanon par lipat jaaye.", "text": "Rajma uske paani ke saath daalein. Gaadhepan ke liye kuch daane kadaahi ki deewaar par masal dein aur dheemi aanch par pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 900, true, null, 'The gravy thickens and coats the beans.', '{"avoid": "Stir from the bottom every few minutes; rajma gravy sticks.", "en": "The gravy thickens and coats the beans.", "heat": "low", "look": "The gravy thickens and coats the beans."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 6, 'Add garam masala and coriander leaves and serve with rice.', '{"en": "Add garam masala and coriander leaves and serve with rice.", "hi": {"smell": "ताज़े गरम मसाले और धनिए की ख़ुशबू।", "text": "गरम मसाला और हरा धनिया डालें और चावल के साथ परोसें।"}, "hi-Latn": {"smell": "Taaze garam masaale aur dhaniye ki khushboo.", "text": "Garam masala aur hara dhaniya daalein aur chaawal ke saath parosein."}}'::jsonb, null, 60, false, null, 'Fresh garam masala and coriander.', '{"en": "Fresh garam masala and coriander.", "smell": "Fresh garam masala and coriander."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'rajma') and step_no > 6;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'rajma');
insert into public.recipe_variation_rules (recipe_id, rule_type, condition, action, note) values
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 'equipment', '{"missing_equipment": "pressure_cooker"}'::jsonb, '{"at_step": 2, "method": "boil", "minutes": 90}'::jsonb, 'Boil hard for the first 10 minutes, then simmer covered until every bean is completely soft.'),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 'time', '{"max_time_min": 45}'::jsonb, '{"requires": "soaked_or_cooked_rajma"}'::jsonb, 'Only quick if the rajma is already soaked or boiled.');

-- Recipe: roti (draft, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('roti', 'Roti (Phulka)', '{"en": "Roti (Phulka)", "hi": "रोटी (फुलका)", "hi-Latn": "Roti (Phulka)"}'::jsonb, 'Soft everyday wheat rotis that puff up on the flame. One katori of atta makes about four rotis. The dough is the whole trick: water a little at a time, a good knead and a rest.', '{"hi": "रोज़ की नरम गेहूँ की रोटी जो आँच पर फूल जाए। एक कटोरी आटे से लगभग चार रोटी बनती हैं। असली बात आटे में है: पानी थोड़ा-थोड़ा, अच्छी तरह गूँधना और थोड़ा आराम।", "hi-Latn": "Roz ki naram gehun ki roti jo aanch par phool jaaye. Ek katori aate se lagbhag chaar roti banti hain. Asli baat aate mein hai: paani thoda-thoda, achchhi tarah goondhna aur thoda aaraam."}'::jsonb, 'generic_north', 'component', 'veg', 2, 30, 15, 2, 1, array['tawa']::text[], array['basics']::text[], '{"acid": 0, "crunch": 0, "heat": 0, "rich": 0.1, "starch": 1, "sweet": 0}'::jsonb, array['grain']::text[], 'curated', 'draft', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
  description = excluded.description, descriptions = excluded.descriptions, cuisine_region = excluded.cuisine_region, course = excluded.course,
  diet = excluded.diet, base_servings = excluded.base_servings, prep_time_min = excluded.prep_time_min,
  cook_time_min = excluded.cook_time_min, difficulty = excluded.difficulty,
  spice_level = excluded.spice_level, equipment = excluded.equipment, tags = excluded.tags,
  flavor_profile = excluded.flavor_profile, food_groups = excluded.food_groups,
  review_status = excluded.review_status, is_published = excluded.is_published;

delete from public.recipe_ingredients where recipe_id = (select id from public.recipes where household_id is null and slug = 'roti');
insert into public.recipe_ingredients (recipe_id, ingredient_id, display_name, quantity, unit, local_measure,
  is_optional, group_name, role, substitutes, sort_order) values
  ((select id from public.recipes where household_id is null and slug = 'roti'), (select id from public.ingredients where canonical_name = 'whole wheat flour'), 'whole wheat flour', 150, 'g', '2 katori atta (8 rotis)', false, null, 'starch', '[]'::jsonb, 0),
  ((select id from public.recipes where household_id is null and slug = 'roti'), (select id from public.ingredients where canonical_name = 'salt'), 'salt', 1, 'g', '1 chutki', true, null, 'spice', '[]'::jsonb, 1),
  ((select id from public.recipes where household_id is null and slug = 'roti'), (select id from public.ingredients where canonical_name = 'ghee'), 'ghee', 9, 'g', '2 chhota chammach', true, null, 'fat', jsonb_build_array(jsonb_build_object('ingredient_id', (select id from public.ingredients where canonical_name = 'butter'), 'ingredient', 'butter', 'ratio', 1, 'note', null)), 2);

insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'roti'), 1, 'Put the atta and salt in a wide bowl. Add about half a katori of water a little at a time, mixing with your fingers, until it comes together.', '{"en": "Put the atta and salt in a wide bowl. Add about half a katori of water a little at a time, mixing with your fingers, until it comes together.", "hi": {"avoid": "सारा पानी एक साथ न डालें: हर बार आटा अलग पानी सोखता है।", "text": "चौड़े बर्तन में आटा और नमक लें। लगभग आधी कटोरी पानी थोड़ा-थोड़ा डालते हुए उँगलियों से मिलाएँ जब तक आटा इकट्ठा न हो जाए।", "touch": "आटा नरम और हल्का चिपचिपा लगे, गीला नहीं। ज़रूरत हो तो एक चम्मच पानी या आटा डालें।"}, "hi-Latn": {"avoid": "Saara paani ek saath na daalein: har baar aata alag paani sokhta hai.", "text": "Chaude bartan mein aata aur namak lein. Lagbhag aadhi katori paani thoda-thoda daalte hue ungliyon se milaayein jab tak aata ikattha na ho jaaye.", "touch": "Aata naram aur halka chipchipa lage, geela nahi. Zaroorat ho to ek chammach paani ya aata daalein."}}'::jsonb, (select id from public.techniques where slug = 'knead'), 180, false, null, 'It should feel soft and slightly sticky, not wet. Add a spoon of water or atta to fix it. Don''t pour all the water at once: atta soaks differently every time.', '{"avoid": "Don''t pour all the water at once: atta soaks differently every time.", "en": "It should feel soft and slightly sticky, not wet. Add a spoon of water or atta to fix it. Don''t pour all the water at once: atta soaks differently every time.", "touch": "It should feel soft and slightly sticky, not wet. Add a spoon of water or atta to fix it."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'roti'), 2, 'Knead with your knuckles, folding the dough over itself, until smooth.', '{"en": "Knead with your knuckles, folding the dough over itself, until smooth.", "hi": {"look": "ऊपर की सतह चिकनी हो जाए, कोई दरार न रहे।", "text": "मुट्ठी से दबाते हुए और आटे को मोड़ते हुए चिकना होने तक गूँधें।", "touch": "उँगली से दबाएँ: गड्ढा धीरे-धीरे वापस भरे। यही नरमी की जाँच है।"}, "hi-Latn": {"look": "Upar ki satah chikni ho jaaye, koi daraar na rahe.", "text": "Mutthi se dabaate hue aur aate ko modte hue chikna hone tak goondhein.", "touch": "Ungli se dabaayein: gaddha dheere-dheere waapas bhare. Yahi narmi ki jaanch hai."}}'::jsonb, (select id from public.techniques where slug = 'knead'), 300, true, null, 'The surface turns smooth with no cracks. Press a finger in: the dent slowly springs back. That is the softness test.', '{"en": "The surface turns smooth with no cracks. Press a finger in: the dent slowly springs back. That is the softness test.", "look": "The surface turns smooth with no cracks.", "touch": "Press a finger in: the dent slowly springs back. That is the softness test."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'roti'), 3, 'Cover the dough with a damp cloth or a lid and let it rest.', '{"en": "Cover the dough with a damp cloth or a lid and let it rest.", "hi": {"text": "आटे को गीले कपड़े या ढक्कन से ढककर आराम करने दें।", "touch": "आराम के बाद आटा और नरम लगे और बेलते समय वापस न सिकुड़े।"}, "hi-Latn": {"text": "Aate ko geele kapde ya dhakkan se dhak kar aaraam karne dein.", "touch": "Aaraam ke baad aata aur naram lage aur belte samay waapas na sikude."}}'::jsonb, null, 1200, true, null, 'After resting it feels softer and rolls without shrinking back.', '{"en": "After resting it feels softer and rolls without shrinking back.", "touch": "After resting it feels softer and rolls without shrinking back."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'roti'), 4, 'Heat the tawa. Make a lemon-sized ball, dust it in dry atta and roll it thin and round.', '{"en": "Heat the tawa. Make a lemon-sized ball, dust it in dry atta and roll it thin and round.", "hi": {"avoid": "सूखा आटा उतना ही लगाएँ कि चिपके नहीं; ज़्यादा आटा तवे पर जलता है।", "look": "एक बराबर गोला, किनारे इतने पतले कि रोशनी लगभग दिखे।", "text": "तवा गरम करें। नींबू जितनी लोई बनाएँ, सूखे आटे में लपेटें और पतली गोल बेलें।"}, "hi-Latn": {"avoid": "Sookha aata utna hi lagaayein ki chipke nahi; zyada aata tawe par jalta hai.", "look": "Ek barabar gola, kinaare itne patle ki roshni lagbhag dikhe.", "text": "Tawa garam karein. Nimbu jitni loi banaayein, sookhe aate mein lapetein aur patli gol belein."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 60, false, null, 'An even circle, thin enough to almost see light through the edges. Use just enough dry atta to stop sticking; too much burns on the tawa.', '{"avoid": "Use just enough dry atta to stop sticking; too much burns on the tawa.", "en": "An even circle, thin enough to almost see light through the edges. Use just enough dry atta to stop sticking; too much burns on the tawa.", "heat": "medium", "look": "An even circle, thin enough to almost see light through the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'roti'), 5, 'Put the roti on the hot tawa. Flip when small bubbles appear, cook the other side a little longer, then hold it over the open flame with tongs so it puffs.', '{"en": "Put the roti on the hot tawa. Flip when small bubbles appear, cook the other side a little longer, then hold it over the open flame with tongs so it puffs.", "hi": {"avoid": "इंडक्शन पर या बिना आँच के, तवे पर ही कपड़े से हल्का दबाएँ।", "look": "ऊपर छोटे बुलबुले, फिर नीचे हल्के भूरे धब्बे।", "safety": "आँच पर चिमटा इस्तेमाल करें, कभी उँगलियाँ नहीं।", "sound": "फूलते समय हल्की सी सीटी जैसी आवाज़।", "text": "रोटी गरम तवे पर डालें। छोटे बुलबुले दिखें तो पलटें, दूसरी तरफ़ थोड़ा ज़्यादा सेकें, फिर चिमटे से सीधी आँच पर रखें ताकि फूल जाए।"}, "hi-Latn": {"avoid": "Induction par ya bina aanch ke, tawe par hi kapde se halka dabaayein.", "look": "Upar chhote bulbule, phir neeche halke bhoore dhabbe.", "safety": "Aanch par chimta istemaal karein, kabhi ungliyaan nahi.", "sound": "Phoolte samay halki si seeti jaisi aawaaz.", "text": "Roti garam tawe par daalein. Chhote bulbule dikhein to paltein, doosri taraf thoda zyada sekein, phir chimte se seedhi aanch par rakhein taaki phool jaaye."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 90, false, null, 'Small bubbles on top, then light brown spots underneath. A soft hiss as it puffs. On induction or without a flame, press the roti gently with a cloth on the tawa instead.', '{"avoid": "On induction or without a flame, press the roti gently with a cloth on the tawa instead.", "en": "Small bubbles on top, then light brown spots underneath. A soft hiss as it puffs. On induction or without a flame, press the roti gently with a cloth on the tawa instead.", "heat": "medium", "look": "Small bubbles on top, then light brown spots underneath.", "sound": "A soft hiss as it puffs."}'::jsonb, null, 'Use tongs over the flame, never your fingers.'),
  ((select id from public.recipes where household_id is null and slug = 'roti'), 6, 'Brush with ghee if you like and keep in a covered box. Leftover dough goes in a closed box in the fridge for up to two days; let it come to room temperature before rolling.', '{"en": "Brush with ghee if you like and keep in a covered box. Leftover dough goes in a closed box in the fridge for up to two days; let it come to room temperature before rolling.", "hi": {"text": "चाहें तो घी लगाएँ और ढके डिब्बे में रखें। बचा आटा बंद डिब्बे में फ़्रिज में दो दिन तक रखें; बेलने से पहले कमरे के तापमान पर आने दें।", "touch": "गरम रोटियाँ ढककर रखने से नरम रहती हैं।"}, "hi-Latn": {"text": "Chaahein to ghee lagaayein aur dhake dibbe mein rakhein. Bacha aata band dibbe mein fridge mein do din tak rakhein; belne se pehle kamre ke taapmaan par aane dein.", "touch": "Garam rotiyaan dhak kar rakhne se naram rehti hain."}}'::jsonb, null, null, false, null, 'Rotis stay soft when stacked and covered while warm.', '{"en": "Rotis stay soft when stacked and covered while warm.", "touch": "Rotis stay soft when stacked and covered while warm."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'roti') and step_no > 6;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'roti');

